insert into topic_content(topic_id,language,content) values('play-group__rhymes-language__c1__t1','English','{"storyTitle":"Bhoo the Cow Says Moo","scenes":[{"emoji":"🐮🌾","title":"Bhoo the Cow","text":"Bhoo the cow lived on a green farm. She loved to say hello to everyone."},{"emoji":"🐮🔊","title":"Moo, Moo!","text":"“Moo, moo!” said Bhoo. Can you say moo like Bhoo? Say it loud!"},{"emoji":"🐶🐱🐑","title":"Friends Come to Play","text":"Dog said “woof”. Cat said “meow”. Sheep said “baa”. Everyone had a different sound."},{"emoji":"🐮🐶🐱🐑🎉","title":"A Happy Farm","text":"All the animals sang together. Woof, meow, baa, moo! What a happy farm!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__rhymes-language__c1__t2','English','{"storyTitle":"Tara the Little Star","scenes":[{"emoji":"⭐🌙🌌","title":"A Star in the Sky","text":"Tara was a tiny star. She lived high up in the dark blue sky."},{"emoji":"✨⭐✨","title":"Twinkle, Twinkle","text":"Tara went twinkle, twinkle! She blinked her light on and off."},{"emoji":"👶👐✨","title":"Your Turn!","text":"Open and close your hands like a twinkling star. Twinkle, twinkle, little star!"},{"emoji":"😴⭐🌙","title":"Good Night, Tara","text":"Tara got sleepy and closed her eyes. Good night, little star."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__rhymes-language__c2__t1','English','{"storyTitle":"Pinku Finds His Face","scenes":[{"emoji":"🐰👀","title":"Two Eyes","text":"Pinku the bunny had two eyes. He used them to see his carrot. Where are your eyes?"},{"emoji":"🐰👃","title":"One Nose","text":"Pinku sniffed with his nose. Sniff, sniff! The carrot smelled sweet. Touch your nose!"},{"emoji":"🐰👂","title":"Two Ears","text":"Pinku had long ears to hear birds sing. Tweet, tweet! Touch your ears!"},{"emoji":"🐰🥕😊","title":"All Together","text":"Eyes to see, nose to smell, ears to hear. Pinku was ready to play!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__rhymes-language__c2__t2','English','{"storyTitle":"Clap and Stomp","scenes":[{"emoji":"👏🐘","title":"Elephant Claps","text":"Ellie the elephant clapped her hands. Clap, clap, clap! Can you clap too?"},{"emoji":"🦶🐘","title":"Elephant Stomps","text":"Ellie stomped her big feet. Stomp, stomp, stomp! The ground shook."},{"emoji":"🤲🍎","title":"Hands Can Hold","text":"Ellie held an apple in her hands. Hands can hold, wave and clap."},{"emoji":"🦶🚶💃","title":"Feet Can Dance","text":"Feet can walk, jump and dance. Ellie danced all the way home."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__numbers__c1__t1','English','{"storyTitle":"One Little Duck","scenes":[{"emoji":"🦆🌊","title":"A Duck on the Pond","text":"One little duck swam on the pond. Just one duck, all alone."},{"emoji":"☝️🦆","title":"One Finger, One Duck","text":"Hold up one finger. One duck, one finger. This is the number one."},{"emoji":"🍎🎈⚽","title":"One of Everything","text":"One apple. One balloon. One ball. Can you find one thing near you?"},{"emoji":"🦆🎉","title":"Quack!","text":"The duck said “Quack!” just one time. One is a small, friendly number."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__numbers__c1__t2','English','{"storyTitle":"Two Shoes and Two Socks","scenes":[{"emoji":"👟👟","title":"Two Shoes","text":"Mia has two shoes, one for each foot. One, two!"},{"emoji":"🧦🧦","title":"Two Socks","text":"She also has two socks. One sock, another sock. That is two."},{"emoji":"✌️👀","title":"Two Fingers, Two Eyes","text":"Hold up two fingers. You also have two eyes and two ears. Pairs are fun!"},{"emoji":"👧👟🧦😊","title":"Ready to Go","text":"Mia put on two socks and two shoes. Now she can run and play!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__numbers__c2__t1','English','{"storyTitle":"The Big Elephant and the Small Mouse","scenes":[{"emoji":"🐘","title":"A Big Elephant","text":"The elephant was very big. Her legs were as big as tree trunks."},{"emoji":"🐭","title":"A Small Mouse","text":"The mouse was very small. He could sit on a leaf."},{"emoji":"🐘🐭","title":"Side by Side","text":"Big elephant, small mouse. One is big and one is small. Which one is big?"},{"emoji":"🐘🐭🤝","title":"Best Friends","text":"Big or small, they played together. Everyone is special."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__numbers__c2__t2','English','{"storyTitle":"The Long Snake and the Short Worm","scenes":[{"emoji":"🐍","title":"A Long Snake","text":"Slinky the snake was very long. He stretched out across the path."},{"emoji":"🪱","title":"A Short Worm","text":"Wiggy the worm was short. He was only as long as your finger."},{"emoji":"🐍🪱","title":"Long and Short","text":"Slinky is long. Wiggy is short. Which one is long?"},{"emoji":"🐍🪱🌈","title":"Wiggle Together","text":"They wiggled along under the rainbow. Long or short, they were happy."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__colours-environment__c1__t1','English','{"storyTitle":"The Red Day","scenes":[{"emoji":"🔴🌞","title":"Today is Red Day","text":"Ruby woke up and said, “Today I will look for red things!”"},{"emoji":"🍎🍓🌹","title":"Red Things in the Garden","text":"She found a red apple, a red strawberry and a red rose. Red is bright!"},{"emoji":"🚗🎈","title":"Red Things Outside","text":"A red car went by. A red balloon floated up. Red was everywhere."},{"emoji":"👧❤️","title":"Ruby’s Red Heart","text":"Ruby drew a big red heart. What red thing can you find?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__colours-environment__c1__t2','English','{"storyTitle":"Sunny and Bubbles","scenes":[{"emoji":"🌞🍌","title":"Sunny is Yellow","text":"Sunny the duckling was yellow like the sun and a banana."},{"emoji":"🌻🐥","title":"Yellow Flowers","text":"A yellow sunflower smiled at Sunny. Yellow makes everyone cheerful."},{"emoji":"💧🐳","title":"Bubbles is Blue","text":"Bubbles the whale was blue like the sea and the sky."},{"emoji":"🌊🐥🐳","title":"Yellow and Blue Friends","text":"Sunny and Bubbles played by the sea. Yellow and blue look lovely together."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__colours-environment__c2__t1','English','{"storyTitle":"Teddy Tours the House","scenes":[{"emoji":"🧸🏠","title":"Teddy’s Home","text":"Teddy lived in a cosy little house with his family."},{"emoji":"🛏️😴","title":"The Bed","text":"Teddy sleeps on a soft bed. Beds are for sleeping at night."},{"emoji":"🪑🍽️","title":"Chair and Table","text":"Teddy sits on a chair and eats at the table. Yum, yum!"},{"emoji":"🧸❤️🏠","title":"Home Sweet Home","text":"Home is where we feel safe and happy. Teddy gave his house a big hug."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('play-group__colours-environment__c2__t2','English','{"storyTitle":"Meet the Family","scenes":[{"emoji":"👩👨","title":"Mummy and Papa","text":"Mummy and Papa love you very much. They give the best hugs."},{"emoji":"👵👴","title":"Dadi and Dada","text":"Grandma and Grandpa tell lovely stories. They love you too."},{"emoji":"👧👦","title":"Brother and Sister","text":"Brothers and sisters play with you. Let’s share our toys!"},{"emoji":"👨‍👩‍👧‍👦❤️","title":"My Family","text":"A family is a group of people who love each other. Wave to your family!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__rhymes-language__c1__t1','English','{"storyTitle":"Ali, Bobo and Coco","scenes":[{"emoji":"🅰️🍎🐜","title":"A for Apple, Ant","text":"Ali the ant found a big red apple. “A, A, Apple!” he said, and gave a happy hop."},{"emoji":"🅱️🐻⚽","title":"B for Bear, Ball","text":"Bobo the bear bounced a bouncy ball. “B, B, Ball!” The ball went boing, boing."},{"emoji":"©️🐱🥥","title":"C for Cat, Coconut","text":"Coco the cat sat beside a coconut. “C, C, Cat!” she purred."},{"emoji":"🅰️🅱️©️🎉","title":"A, B, C Together","text":"The three friends held hands. “A, B, C!” they sang. Can you sing it too?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__rhymes-language__c1__t2','English','{"storyTitle":"The Dog, the Egg and the Fish","scenes":[{"emoji":"🐶🥁","title":"D for Dog, Drum","text":"Danny the dog played a drum. “D, D, Dog!” Boom, boom, boom!"},{"emoji":"🥚🐘","title":"E for Egg, Elephant","text":"Ellie the elephant found a white egg. “E, E, Egg!” she trumpeted."},{"emoji":"🐟🌸","title":"F for Fish, Flower","text":"Fifi the fish swam by a flower. “F, F, Fish!” she blew bubbles."},{"emoji":"🔤🎊","title":"Six Letters Now","text":"A, B, C, D, E, F! Danny, Ellie and Fifi cheered for all six letters."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__rhymes-language__c2__t1','English','{"storyTitle":"The Star Show","scenes":[{"emoji":"🌙⭐","title":"Night Falls","text":"The sun went to sleep and the moon came out. Little stars began to wake up."},{"emoji":"✨👐","title":"Twinkle, Twinkle","text":"The stars blinked on and off. Children opened and closed their hands like stars."},{"emoji":"👀☝️⭐","title":"Up Above the World","text":"“How I wonder what you are!” the children said, pointing up to the sky."},{"emoji":"🌟😴","title":"Sleepy Time","text":"The stars kept shining as the children yawned. Sweet dreams, little ones."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__rhymes-language__c2__t2','English','{"storyTitle":"Black Sheep’s Wool","scenes":[{"emoji":"🐑🧶","title":"Black Sheep","text":"Baa Baa the black sheep had lots of soft wool on his back."},{"emoji":"🙋‍♂️🛍️","title":"Three Bags Full","text":"“Do you have any wool?” asked the farmer. “Yes sir, yes sir, three bags full!”"},{"emoji":"1️⃣2️⃣3️⃣","title":"One, Two, Three","text":"One bag for the master, one for the dame, one for the little boy down the lane."},{"emoji":"🙏😊","title":"Thank You!","text":"Everyone said thank you. Saying please and thank you makes people smile."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__numbers__c1__t1','English','{"storyTitle":"Three Little Birds","scenes":[{"emoji":"1️⃣🐦","title":"One Bird","text":"One little bird sat on a branch. One bird says tweet."},{"emoji":"2️⃣🐦🐦","title":"Two Birds","text":"A friend flew in. Now there were two birds. Tweet, tweet!"},{"emoji":"3️⃣🐦🐦🐦","title":"Three Birds","text":"Another bird joined them. Three birds sang a song. Count with me: one, two, three."},{"emoji":"🐦🐦🐦🌳","title":"Sing Together","text":"The three birds sang in the tree. Each bird counted once, and the number grew."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__numbers__c1__t2','English','{"storyTitle":"Four and Five Balloons","scenes":[{"emoji":"4️⃣🎈","title":"Four Balloons","text":"Rohan had four balloons: red, blue, green, yellow. One, two, three, four."},{"emoji":"5️⃣🎈","title":"A Fifth Balloon","text":"His sister gave him one more. Now there were five balloons."},{"emoji":"🖐️🎈","title":"Five Fingers","text":"Rohan held up five fingers. One for each balloon. Five is one whole hand."},{"emoji":"🎈🎈🎈🎈🎈🎉","title":"Party Time","text":"Five balloons floated up. Pop, pop! Rohan counted five happy faces."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__numbers__c2__t1','English','{"storyTitle":"Circle and Square Play","scenes":[{"emoji":"⭕🌞","title":"Round Like a Circle","text":"Cici the circle rolled like a wheel. The sun and a ball are circles too."},{"emoji":"🟦🪟","title":"Square Has Four Sides","text":"Sammy the square had four equal sides. A window is shaped like a square."},{"emoji":"🍪🧇","title":"Spot the Shapes","text":"A round biscuit is a circle. A square sandwich has four sides. Which do you see?"},{"emoji":"⭕🟦🤝","title":"Both Special","text":"Cici can roll. Sammy can stack. Both shapes are useful!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__numbers__c2__t2','English','{"storyTitle":"Tilly and Rex","scenes":[{"emoji":"🔺⛺","title":"Triangle Has Three Sides","text":"Tilly the triangle has three sides and three corners, like a tent."},{"emoji":"📏📚","title":"Rectangle is Long","text":"Rex the rectangle is long, like a book or a door."},{"emoji":"🚪🍕","title":"Find Them","text":"A door is a rectangle. A slice of pizza is a triangle. Look around you!"},{"emoji":"🔺🟧🎉","title":"Shape Fun","text":"Tilly and Rex made a house together: a rectangle with a triangle roof."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__colours-environment__c1__t1','English','{"storyTitle":"Green Frog, Orange Orange","scenes":[{"emoji":"🐸🍃","title":"Freddy is Green","text":"Freddy the frog is green like leaves and grass."},{"emoji":"🥒🥦","title":"Green Food","text":"Cucumber and broccoli are green too. Green food helps us grow strong."},{"emoji":"🍊🥕","title":"Orange Things","text":"An orange is orange. So is a carrot! Orange things taste sweet and crunchy."},{"emoji":"🐸🍊🌈","title":"Colour Picnic","text":"Freddy had a picnic with green peas and orange slices. What colours can you see?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__colours-environment__c1__t2','English','{"storyTitle":"The Magic Paint Pots","scenes":[{"emoji":"🎨🖌️","title":"Three Paint Pots","text":"Maya found pots of red, yellow and blue paint. What can they make?"},{"emoji":"💛💙💚","title":"Yellow and Blue","text":"Maya mixed yellow and blue. Splash! The paint turned green like a leaf."},{"emoji":"❤️💛🧡","title":"Red and Yellow","text":"Next she mixed red and yellow. Swish! The paint turned orange like a sunset."},{"emoji":"🖼️🌈","title":"A Rainbow Picture","text":"Maya painted a rainbow with all her new colours. Colours are magic!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__colours-environment__c2__t1','English','{"storyTitle":"The Fruit Basket","scenes":[{"emoji":"🧺🍎","title":"A Basket of Fruits","text":"Grandma brought a basket full of fruits for the children."},{"emoji":"🍌🍇","title":"Banana and Grapes","text":"A yellow banana and purple grapes. “Which do you want?” she asked."},{"emoji":"🥭🍉","title":"Mango and Watermelon","text":"Sweet mango and juicy watermelon. Yum, yum!"},{"emoji":"😋🍎🍌🍇","title":"Fruits are Good","text":"Fruits taste good and keep us healthy. We say thank you, Grandma!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('nursery__colours-environment__c2__t2','English','{"storyTitle":"Home Pets and Jungle Pets","scenes":[{"emoji":"🐶🐱","title":"Pets at Home","text":"A dog and a cat live in a house. They are pets and play with us."},{"emoji":"🦁🐘","title":"Wild Animals","text":"A lion and an elephant live in the jungle. They are wild animals."},{"emoji":"🏠🌳","title":"Different Homes","text":"Pets live in houses. Wild animals live in forests. Where do you live?"},{"emoji":"🐶🦁🤗","title":"Be Kind","text":"We are kind to all animals. We never scare or hurt them."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__rhymes-language__c1__t1','English','{"storyTitle":"Four Friends on the Hill","scenes":[{"emoji":"🍇🐐","title":"G for Goat, Grapes","text":"Gina the goat nibbled green grapes. “G, G, Goat!” she said."},{"emoji":"🏠🐴","title":"H for House, Horse","text":"Hari the horse lived in a little house. “H, H, Horse!” he neighed."},{"emoji":"🍦🏝️","title":"I for Ice-cream, Island","text":"Ira licked a cold ice-cream on an island. “I, I, Ice-cream!”"},{"emoji":"🪼🧃","title":"J for Jug, Jelly","text":"Jojo poured juice from a jug. “J, J, Jug!” G, H, I, J were all friends."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__rhymes-language__c1__t2','English','{"storyTitle":"The Alphabet Train, Part Two","scenes":[{"emoji":"🪁🐨","title":"K for Kite, Koala","text":"A kite flew high above a koala. “K, K, Kite!”"},{"emoji":"🦁🍋","title":"L for Lion, Lemon","text":"A lion sniffed a sour lemon. “L, L, Lion!” and made a funny face."},{"emoji":"🥭🌙","title":"M for Mango, Moon","text":"Mina ate a mango under the moon. “M, M, Mango!”"},{"emoji":"🪺🐙🐧","title":"N, O, P","text":"Nest, octopus, penguin. N, O, P! The alphabet train chugged on."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__rhymes-language__c2__t1','English','{"storyTitle":"The Word Magic Wand","scenes":[{"emoji":"🪄🔤","title":"A Magic Wand","text":"Pia found a magic wand. When she said sounds together, they turned into words!"},{"emoji":"🐱","title":"C-A-T","text":"C, a, t… cat! A furry cat appeared. Pia clapped."},{"emoji":"🦇🎩","title":"B-A-T and H-A-T","text":"B, a, t… bat! H, a, t… hat! Bat and hat sound the same at the end."},{"emoji":"✨📖","title":"Reading Time","text":"Pia could read three new words. Can you blend C-A-T too?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__rhymes-language__c2__t2','English','{"storyTitle":"Reading with Pip","scenes":[{"emoji":"🐧📌","title":"Pin","text":"Pip the penguin found a pin. P, i, n… pin!"},{"emoji":"🖊️🐓","title":"Pen and Hen","text":"P, e, n… pen! H, e, n… hen! The hen clucked at the pen."},{"emoji":"🍲🔥","title":"Pot","text":"P, o, t… pot! The hot pot had soup in it."},{"emoji":"🐧📚","title":"Pip Can Read","text":"Pip read pin, pen, hen and pot. Every word is made of tiny sounds."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__numbers__c1__t1','English','{"storyTitle":"Ten Little Ducks","scenes":[{"emoji":"6️⃣🦆","title":"Six Ducks","text":"Six ducks waddled to the pond. One, two, three, four, five, six."},{"emoji":"7️⃣8️⃣🦆","title":"Seven and Eight","text":"Two more arrived. Seven ducks, then eight ducks."},{"emoji":"9️⃣🔟🦆","title":"Nine and Ten","text":"Two more came. Nine ducks, then ten! Ten ducks splashed together."},{"emoji":"🔟🙌","title":"Two Hands, Ten Fingers","text":"You have ten fingers on two hands. Count your fingers with the ducks!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__numbers__c1__t2','English','{"storyTitle":"The Bus to Twenty","scenes":[{"emoji":"🚌🔟","title":"Ten on the Bus","text":"Ten children sat on the bus. Ten is a full group."},{"emoji":"1️⃣1️⃣🧒","title":"Eleven, Twelve","text":"One more child got on: eleven. Another: twelve!"},{"emoji":"🧒🧒🧒","title":"Counting On","text":"Thirteen, fourteen, fifteen… more kids hopped on, one at a time."},{"emoji":"2️⃣0️⃣🎉","title":"Twenty!","text":"At last, twenty children sang on the bus. Ten and ten make twenty."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__numbers__c2__t1','English','{"storyTitle":"The Bead Necklace","scenes":[{"emoji":"📿🔴🔵","title":"Red, Blue","text":"Tina threaded a red bead, then a blue bead. A pattern began."},{"emoji":"🔴🔵🔴🔵","title":"Again and Again","text":"Red, blue, red, blue. A pattern is something that repeats."},{"emoji":"🔴🔵🟡","title":"A New Pattern","text":"Next she made red, blue, yellow, red, blue, yellow. What comes next?"},{"emoji":"📿😍","title":"A Pretty Necklace","text":"Tina’s necklace was full of patterns. She wore it proudly."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__numbers__c2__t2','English','{"storyTitle":"Monkey Moves","scenes":[{"emoji":"🐒⬆️🌴","title":"Up the Tree","text":"Momo the monkey climbed up the tree. Up, up, up!"},{"emoji":"🐒⬇️","title":"Down He Comes","text":"Then Momo slid down. Down, down, down!"},{"emoji":"🐒📦","title":"In the Box","text":"Momo hopped in the box. Now he was in. Then he hopped out!"},{"emoji":"🐒🙌","title":"Do It With Momo","text":"Can you go up on tiptoe and down in a squat? In and out of a hoop?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__colours-environment__c1__t1','English','{"storyTitle":"Pinky and Her Five Helpers","scenes":[{"emoji":"👁️🌈","title":"Eyes See","text":"Pinky’s eyes saw a bright rainbow. Eyes help us see."},{"emoji":"👂🎵","title":"Ears Hear","text":"Her ears heard music. Ears help us hear."},{"emoji":"👃🌹","title":"Nose Smells","text":"Her nose smelled a sweet rose. The nose helps us smell."},{"emoji":"👅✋","title":"Tongue and Hands","text":"Her tongue tasted a sweet laddoo. Her hands felt soft fur. We taste and touch too!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__colours-environment__c1__t2','English','{"storyTitle":"Clean Clive","scenes":[{"emoji":"🧼🙌","title":"Wash Your Hands","text":"Clive the elephant washed his hands with soap before eating. Splish, splash!"},{"emoji":"🪥😁","title":"Brush Your Teeth","text":"He brushed his teeth in the morning and at night. Shiny teeth!"},{"emoji":"🛁🫧","title":"Bath Time","text":"He took a bubble bath every day. Scrub, scrub, scrub."},{"emoji":"🐘✨","title":"Fresh and Healthy","text":"Clean Clive felt fresh and strong. Cleanliness keeps germs away."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__colours-environment__c2__t1','English','{"storyTitle":"Weather Watchers","scenes":[{"emoji":"☀️🧢","title":"A Sunny Day","text":"It was sunny and hot. The children wore caps and drank water."},{"emoji":"🌧️☔","title":"A Rainy Day","text":"Rain fell, pitter-patter. The children carried umbrellas and splashed in puddles."},{"emoji":"💨🪁","title":"A Windy Day","text":"The wind blew and the kite flew high. Whoosh!"},{"emoji":"🌈😊","title":"Rainbow Time","text":"After the rain the sun came out and made a rainbow. Which weather do you like?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('lkg__colours-environment__c2__t2','English','{"storyTitle":"Three Seasons","scenes":[{"emoji":"🍦🥭☀️","title":"Summer","text":"In summer it is hot. We eat ice-cream and mangoes and wear light clothes."},{"emoji":"🌧️🐸","title":"Rainy Season","text":"In the rainy season, clouds bring rain. Frogs sing and plants grow green."},{"emoji":"🧣🧤❄️","title":"Winter","text":"In winter it is cold. We wear sweaters and sip warm soup."},{"emoji":"🔄🌍","title":"Round and Round","text":"The seasons come one after another all year. Each one is special."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__rhymes-language__c1__t1','English','{"storyTitle":"The Alphabet Race, Part Three","scenes":[{"emoji":"👸🐰","title":"Q and R","text":"A queen met a rabbit. “Q for Queen, R for Rabbit!” they said."},{"emoji":"🐍🐢","title":"S and T","text":"A snake raced a tortoise. “S for Snake, T for Tortoise!” The tortoise won slowly."},{"emoji":"☂️🎻","title":"U and V","text":"Uma held an umbrella while Vikram played the violin. “U, V!”"},{"emoji":"🏁🔤","title":"Almost There","text":"Q, R, S, T, U, V! Only four letters were left in the race."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__rhymes-language__c1__t2','English','{"storyTitle":"The Alphabet Finish Line","scenes":[{"emoji":"🐋🪟","title":"W for Whale","text":"A whale looked in through a window. “W, W, Whale!”"},{"emoji":"🎶🩻","title":"X for Xylophone","text":"Xena played a xylophone. “X” sounds like the end of box and fox."},{"emoji":"🪀🦓","title":"Y and Z","text":"A yo-yo and a zebra! “Y for Yo-yo, Z for Zebra!”"},{"emoji":"🏆🔤🎉","title":"A to Z!","text":"All twenty-six letters crossed the line. Let’s sing the alphabet song from A to Z!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__rhymes-language__c2__t1','English','{"storyTitle":"Sam Says a Sentence","scenes":[{"emoji":"👦🐱","title":"I See a Cat","text":"Sam looked out the window. “I see a cat,” he said. Four words made a sentence."},{"emoji":"🧱➡️","title":"Words in a Row","text":"Words go in a row, like blocks. “I see a dog.” “I see a bird.”"},{"emoji":"🔠📍","title":"Capital and Full Stop","text":"A sentence starts with a capital letter and ends with a full stop."},{"emoji":"✍️🎉","title":"Write Your Own","text":"Sam wrote his own sentence: “I like my cat.” Can you write one?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__rhymes-language__c2__t2','English','{"storyTitle":"The Opposite Twins","scenes":[{"emoji":"🔥❄️","title":"Hot and Cold","text":"Hot tea and cold ice-cream are opposites."},{"emoji":"😀😢","title":"Happy and Sad","text":"Happy has a smile. Sad has a tear. They are opposites too."},{"emoji":"⬆️⬇️","title":"Up and Down","text":"The lift goes up and then comes down. Day and night, open and shut."},{"emoji":"👯🎉","title":"Twin Words","text":"Opposites come in pairs, like twins. Think of more pairs!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__numbers__c1__t1','English','{"storyTitle":"The Ten-Stick Farm","scenes":[{"emoji":"🌽🔟","title":"A Bundle of Ten","text":"A farmer tied ten corn cobs in a bundle. That is one ten."},{"emoji":"🌽🌽🔟🔟","title":"More Bundles","text":"Two bundles make 20. Three bundles make 30."},{"emoji":"4️⃣0️⃣5️⃣0️⃣","title":"Forty and Fifty","text":"Four bundles make 40. Five bundles make 50."},{"emoji":"🧑‍🌾🎉","title":"Count Quick","text":"Counting by tens is quick. 10, 20, 30, 40, 50!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__numbers__c1__t2','English','{"storyTitle":"The Number Neighbours","scenes":[{"emoji":"🏘️🔢","title":"A Street of Numbers","text":"Numbers live on a street, in order, like houses."},{"emoji":"⬅️5️⃣","title":"Before","text":"The neighbour before 5 is 4. “Before” means one less."},{"emoji":"5️⃣➡️","title":"After","text":"The neighbour after 5 is 6. “After” means one more."},{"emoji":"🎯🔢","title":"In Between","text":"Between 7 and 9 lives 8. Can you find the number between 14 and 16?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__numbers__c2__t1','English','{"storyTitle":"Fruit Stall Adding","scenes":[{"emoji":"🍎🍎🍎","title":"Three Apples","text":"Raj had three apples at his fruit stall."},{"emoji":"🍎🍎➕","title":"Two More","text":"A friend brought two more apples. How many now?"},{"emoji":"3️⃣➕2️⃣🟰5️⃣","title":"Three Plus Two","text":"Three apples and two apples make five apples. We write 3 + 2 = 5."},{"emoji":"🖐️😊","title":"Use Your Fingers","text":"Put up three fingers, then two more. Count them all: five!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__numbers__c2__t2','English','{"storyTitle":"The Cookie Jar","scenes":[{"emoji":"🍪🍪🍪🍪🍪","title":"Five Cookies","text":"Neha had five cookies in a jar."},{"emoji":"😋🍪","title":"Yum!","text":"She ate two cookies. Now some were gone."},{"emoji":"5️⃣➖2️⃣🟰3️⃣","title":"Five Minus Two","text":"Five take away two leaves three. We write 5 − 2 = 3."},{"emoji":"🍪🍪🍪👧","title":"Three Left","text":"Neha counted three cookies left. Taking away makes the group smaller."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__colours-environment__c1__t1','English','{"storyTitle":"Helpers in Our Town","scenes":[{"emoji":"👩‍⚕️🩺","title":"Doctor","text":"The doctor checks us when we are sick and helps us get well."},{"emoji":"👩‍🏫📚","title":"Teacher","text":"The teacher helps us learn to read, write and count."},{"emoji":"👮🚔","title":"Police Officer","text":"The police officer keeps everyone safe and helps when we are lost."},{"emoji":"🙏🏘️","title":"Thank You, Helpers","text":"Our town runs well because helpers do their work. We say thank you!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__colours-environment__c1__t2','English','{"storyTitle":"From Farm to Plate","scenes":[{"emoji":"👨‍🌾🌾","title":"Farmer","text":"The farmer grows rice, wheat and vegetables in the fields."},{"emoji":"🧑‍🍳🍛","title":"Cook","text":"The cook turns the grains and vegetables into tasty meals."},{"emoji":"📮🚲","title":"Postman","text":"The postman rides around town bringing letters and parcels."},{"emoji":"🤝😊","title":"Everyone Helps","text":"Every helper has an important job. Which helper would you like to be?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__colours-environment__c2__t1','English','{"storyTitle":"Little Plant’s Body","scenes":[{"emoji":"🌱🟤","title":"Roots","text":"Roots hold the plant in the soil and drink water."},{"emoji":"🌿","title":"Stem","text":"The stem holds the plant up and carries water to the leaves."},{"emoji":"🍃☀️","title":"Leaves","text":"Leaves catch sunlight to make food for the plant."},{"emoji":"🌸🐝","title":"Flower","text":"Flowers are pretty and bees love them. Later, flowers can become fruits."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('ukg__colours-environment__c2__t2','English','{"storyTitle":"Home Sweet Animal Home","scenes":[{"emoji":"🐦🪺","title":"Birds Live in Nests","text":"The bird built a nest of twigs high in the tree."},{"emoji":"🐝🍯","title":"Bees Live in Hives","text":"Bees make honey in a hive. They work together."},{"emoji":"🐰🕳️","title":"Rabbits Live in Burrows","text":"The rabbit dug a burrow underground. It is safe and warm."},{"emoji":"🐟💧","title":"Fish Live in Water","text":"Fish swim in ponds and seas. Every animal has a home that fits it."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__mathematics__c1__t1','English','{"storyTitle":"Tens and Ones at the Mango Stall","scenes":[{"emoji":"🥭🥭🛒","title":"Mangoes Everywhere","text":"Mohan sold mangoes at a stall. He tied ten mangoes in each bag so counting would be easy."},{"emoji":"🛍️🛍️🥭🥭🥭","title":"Bags of Ten","text":"Two full bags and three loose mangoes made 23. The 2 tells us tens and the 3 tells us ones."},{"emoji":"🔢🔟","title":"Place Value","text":"In every number each digit has a place. The place decides what the digit is worth."},{"emoji":"😊🥭🔟","title":"Quick Counting","text":"Mohan counted by tens, then added the ones. Place value makes big counting quick."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__mathematics__c1__t2','English','{"storyTitle":"Which Number is Bigger?","scenes":[{"emoji":"🎈🎈👧👦","title":"Two Bunches of Balloons","text":"Rita had 18 balloons and Sam had 24. “Who has more?” asked Mum."},{"emoji":"🔟🔟🆚🔟","title":"Look at the Tens First","text":"Rita had 1 ten and Sam had 2 tens. Two tens is more than one ten."},{"emoji":"⚖️🔢","title":"Greater, Smaller, Equal","text":"So 24 is greater than 18, and 18 is smaller than 24. If both are the same, they are equal."},{"emoji":"1️⃣2️⃣3️⃣","title":"Counting in Order","text":"Rita lined up the numbers from smallest to biggest. Comparing helps us put numbers in order."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__mathematics__c2__t1','English','{"storyTitle":"Adding Marbles","scenes":[{"emoji":"🔴🔴🔴🔴👧","title":"Four Marbles","text":"Tara had 4 red marbles in her pocket. She was proud of her small collection."},{"emoji":"🔵🔵🔵🤝","title":"Friends Share","text":"Her friend gave her 3 blue marbles. Now how many were there in all?"},{"emoji":"🔴🔴🔴🔴➕🔵🔵🔵","title":"Putting Together","text":"Adding means putting groups together. 4 and 3 make 7 marbles."},{"emoji":"8️⃣🔢","title":"Counting On","text":"For 8 + 5, start at 8 and count on: 9, 10, 11, 12, 13. The answer is 13."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__mathematics__c2__t2','English','{"storyTitle":"Shopping with Change","scenes":[{"emoji":"👦✏️🛒","title":"At the Shop","text":"Aman went to buy a pencil for ₹8. He gave the shopkeeper a ten-rupee note."},{"emoji":"💵🪙🪙","title":"How Much Change?","text":"The shopkeeper had to give back the extra money. That is 10 − 8, which is ₹2."},{"emoji":"➖🔴🔴","title":"Taking Away","text":"Subtracting means taking away. If Tara lost 2 of her 7 marbles, 5 are left."},{"emoji":"🛒😄🪙","title":"Maths in the Market","text":"Adding finds the total. Subtracting finds what is left. Both help us shop wisely."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__mathematics__c3__t1','English','{"storyTitle":"Shapes in the Playground","scenes":[{"emoji":"👧🛝","title":"A Playground Walk","text":"Leela went to the playground and saw shapes in everything. “Look, shapes!” she said."},{"emoji":"⚽⭕","title":"Round Things","text":"The ball was a sphere. The ring toss hoops were circles."},{"emoji":"📦🥁","title":"Boxes and Blocks","text":"The toy boxes were cubes and a drum was a cylinder. Some shapes are flat and some are solid."},{"emoji":"🔺🟦","title":"Sides and Corners","text":"A triangle has 3 sides and 3 corners. A square has 4 equal sides."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__mathematics__c3__t2','English','{"storyTitle":"The Rangoli Pattern","scenes":[{"emoji":"🪔🎨","title":"Diwali Rangoli","text":"Anu drew a rangoli at her door with coloured powder."},{"emoji":"🔴🟡🔴🟡","title":"Repeat the Colours","text":"Red, yellow, red, yellow. A repeating pattern goes over and over."},{"emoji":"2️⃣4️⃣6️⃣","title":"Number Patterns","text":"2, 4, 6, 8… numbers can make patterns too. Each one goes up by two."},{"emoji":"🌸✨","title":"A Beautiful Rangoli","text":"Everyone loved her pattern. Spotting patterns helps us guess what comes next."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__english__c1__t1','English','{"storyTitle":"Sounds That Make Words","scenes":[{"emoji":"👧🔊","title":"Little Sounds","text":"Every letter has a sound. Priya learned that c says “k”, a says “a” and t says “t”."},{"emoji":"🧩🔤","title":"Blend Them","text":"Priya pushed the sounds together: k-a-t, cat! Blending the sounds makes a word."},{"emoji":"🐱🎩🦇","title":"Words That Rhyme","text":"Cat, hat, bat. They end with the same sounds, so they rhyme."},{"emoji":"📖😃","title":"I Can Read!","text":"Priya read her first little book all by herself."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__english__c1__t2','English','{"storyTitle":"The Word Wall","scenes":[{"emoji":"🧱📝","title":"A Wall of Words","text":"Teacher built a word wall. “Some words are so common we should know them by sight.”"},{"emoji":"👀🔤","title":"The and Is","text":"“The cat is big.” The words the and is show up everywhere."},{"emoji":"🧑‍🤝‍🧑🙋","title":"We and Can","text":"“We can run.” We and can join words into little sentences."},{"emoji":"🏆📚","title":"Word Wall Star","text":"Rahul could read all the words. Reading sight words fast makes stories easier."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__english__c2__t1','English','{"storyTitle":"The Name Detective","scenes":[{"emoji":"🕵️🔍","title":"Detective Nina","text":"Nina the detective looked for naming words in the classroom."},{"emoji":"👩‍🏫🧒","title":"People Names","text":"Teacher and Ravi are names of people. They are naming words."},{"emoji":"🐕🏫🪑","title":"Animals, Places, Things","text":"Dog, school and chair name an animal, a place and a thing."},{"emoji":"📒🌟","title":"Case Closed","text":"Nouns are naming words. Nina found twenty of them!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__english__c2__t2','English','{"storyTitle":"Action Island","scenes":[{"emoji":"🏝️🏃","title":"Welcome to Action Island","text":"On Action Island, everyone was always doing something."},{"emoji":"🏃🪁","title":"Run and Fly","text":"“Run!” cried the girl. “Fly!” cried the kite. Run and fly are action words."},{"emoji":"🍽️😴","title":"Eat and Sleep","text":"The boy eats. The cat sleeps. Eat and sleep are action words too."},{"emoji":"🙌🎉","title":"Act It Out","text":"Can you jump, clap and spin? Words that tell what we do are action words."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__evs__c1__t1','English','{"storyTitle":"Bholu Learns About His Body","scenes":[{"emoji":"🧒🪞","title":"Look in the Mirror","text":"Bholu looked in the mirror. He saw head, arms, legs and tummy."},{"emoji":"👀👂👃","title":"Face Parts","text":"Eyes help us see. Ears help us hear. The nose helps us smell."},{"emoji":"🖐️🦵","title":"Hands and Legs","text":"Hands help us pick things up. Legs help us walk and run."},{"emoji":"❤️💪","title":"Take Care","text":"Bholu eats healthy food and exercises. A healthy body feels great!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__evs__c1__t2','English','{"storyTitle":"The Sharma Family","scenes":[{"emoji":"👨‍👩‍👧‍👦🏠","title":"A Big Family","text":"Meera lived with her parents, brother and grandparents."},{"emoji":"👵📖","title":"Grandma","text":"Grandma told stories at bedtime. Grandpa taught Meera chess."},{"emoji":"🍳🧹","title":"Everyone Helps","text":"Mum cooked, Dad fixed things, and Meera set the table."},{"emoji":"🥰🏡","title":"Together We Are Strong","text":"Families share love and work. What do you do to help at home?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__evs__c2__t1','English','{"storyTitle":"The Seed that Slept","scenes":[{"emoji":"🌰🌱","title":"A Sleepy Seed","text":"Meena planted a tiny seed in a pot. It slept quietly in the dark soil."},{"emoji":"💧☀️","title":"Water and Sunshine","text":"Every morning Meena gave it water and put it in the sun."},{"emoji":"🌱⬇️","title":"Roots Grow Down","text":"After a few days, tiny roots grew down into the soil."},{"emoji":"🌿☀️","title":"The Shoot Rises","text":"A little green shoot pushed up toward the light. The seed had woken up."}],"questions":[{"type":"MCQ","q":"What does a seed need to start growing?","options":["Water and warmth","Loud music","Plastic","A toy"],"answer":0,"concept":"What seeds need"},{"type":"MCQ","q":"Which part of the seed grows down into the soil first?","options":["Root","Leaf","Flower","Fruit"],"answer":0,"concept":"Roots"},{"type":"True/False","q":"Plants need sunlight to grow.","options":["True","False"],"answer":0,"concept":"Sunlight"},{"type":"MCQ","q":"A small green shoot pushes up toward which of these?","options":["Light","A rock","A wall","The dark"],"answer":0,"concept":"Shoot"},{"type":"Application","q":"Meena forgot to water her seed pot for many days. What will most likely happen?","options":["The seed grows well","The seed may not grow","The pot becomes a tree","Nothing at all"],"answer":1,"concept":"Water"}],"strong":["What seeds need","Roots","Sunlight"],"weak":["Shoot","Water"],"reteach":{"concept":"Why seeds need water","visual":"🌰 + 💧 + ☀️ → 🌱","card":"Think of a seed as a sleepy child. Water is like a morning drink that wakes the seed up so it can start to grow.","q":"What does water do for the seed?","options":["Helps it wake up and grow","Makes it fly","Turns it into a stone","Keeps it asleep forever"],"answer":0}}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__evs__c2__t2','English','{"storyTitle":"The Vegetable Garden","scenes":[{"emoji":"🥕🌱","title":"Roots We Eat","text":"Dadu pulled a carrot from the soil. The carrot is a root."},{"emoji":"🥬🌿","title":"Leaves We Eat","text":"Spinach and cabbage are leaves. Green leaves are full of goodness."},{"emoji":"🍅🍆","title":"Fruits We Eat","text":"Tomatoes and brinjals grow from flowers. They are fruits."},{"emoji":"🌾🍚","title":"Seeds We Eat","text":"Rice and wheat are seeds. Plants give us lots of our food."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__hindi__c1__t1','English','{"storyTitle":"स्वरों की सैर","scenes":[{"emoji":"🍃🐜","title":"अ से अनार","text":"अनु चींटी को एक लाल अनार मिला। “अ से अनार!” उसने खुश होकर कहा।"},{"emoji":"🥭🌟","title":"आ से आम","text":"आगे उसे मीठा आम मिला। “आ से आम!” आम बहुत रसीला था।"},{"emoji":"🐛🪔","title":"इ से इमली","text":"इमली खट्टी थी। उसने मुँह बनाया। “इ से इमली!”"},{"emoji":"🔤🎉","title":"स्वर ही स्वर","text":"अ, आ, इ, ई, उ, ऊ… सब स्वर साथ-साथ नाचने लगे।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__hindi__c1__t2','English','{"storyTitle":"मात्रा जादू","scenes":[{"emoji":"🪄✨","title":"जादू की छड़ी","text":"मीना को एक जादू की छड़ी मिली। वह अक्षरों में मात्रा लगा सकती थी।"},{"emoji":"🐕📖","title":"आ की मात्रा","text":"क में आ की मात्रा लगी, तो बना “का”। “काम” और “काला” भी बने।"},{"emoji":"📚🔖","title":"इ की मात्रा","text":"क में इ की मात्रा लगी, तो बना “कि”। “किताब” शब्द बन गया।"},{"emoji":"📚😄","title":"मैं पढ़ सकती हूँ","text":"मीना अब आसान शब्द पढ़ सकती थी। मात्राएँ शब्दों को सुंदर बनाती हैं।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__hindi__c2__t1','English','{"storyTitle":"मेरा घर","scenes":[{"emoji":"🏠😊","title":"मेरा घर","text":"यह मेरा घर है। इसमें मम्मी, पापा और दादी रहते हैं।"},{"emoji":"🛏️🪑","title":"बिस्तर और कुर्सी","text":"मेरे कमरे में बिस्तर है। मेज़ के पास कुर्सी है।"},{"emoji":"🍚🥛","title":"रसोई","text":"रसोई में दाल-चावल बनता है। दूध भी रखा है।"},{"emoji":"🏡❤️","title":"प्यारा घर","text":"घर में सब प्यार से रहते हैं। घर सबसे प्यारी जगह है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__hindi__c2__t2','English','{"storyTitle":"बाज़ार की सैर","scenes":[{"emoji":"🧺👦","title":"बाज़ार चलो","text":"रवि अपनी माँ के साथ बाज़ार गया। वहाँ रंग-बिरंगे फल-सब्ज़ियाँ थीं।"},{"emoji":"🍎🍌🥭","title":"फल","text":"सेब, केला और आम मीठे फल हैं। रवि को आम सबसे अच्छा लगा।"},{"emoji":"🥔🍅🥕","title":"सब्ज़ियाँ","text":"आलू, टमाटर और गाजर सब्ज़ियाँ हैं। इनसे सब्ज़ी बनती है।"},{"emoji":"😋🛍️","title":"स्वस्थ रहो","text":"फल और सब्ज़ियाँ खाने से हम स्वस्थ रहते हैं।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__hindi__c3__t1','English','{"storyTitle":"प्यासा कौआ","scenes":[{"emoji":"🐦☀️","title":"गर्मी का दिन","text":"गर्मी का दिन था। एक कौआ बहुत प्यासा था। वह पानी ढूँढ़ने उड़ा।"},{"emoji":"🏺💧","title":"घड़ा मिला","text":"उसे एक घड़ा दिखा। उसमें थोड़ा-सा पानी था, पर कौए की चोंच वहाँ तक नहीं पहुँची।"},{"emoji":"🪨🏺","title":"कंकड़ डाले","text":"कौए ने एक-एक कंकड़ घड़े में डाला। पानी ऊपर आने लगा।"},{"emoji":"🐦😄","title":"पानी पिया","text":"कौए ने जी भरकर पानी पिया। सीख: समझदारी से हर मुश्किल हल होती है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-1__hindi__c3__t2','English','{"storyTitle":"चतुर खरगोश","scenes":[{"emoji":"🦁🌲","title":"जंगल का राजा","text":"जंगल में एक शेर रहता था। वह रोज़ जानवरों को परेशान करता था।"},{"emoji":"🐰🤔","title":"खरगोश की सोच","text":"एक छोटे खरगोश ने एक तरकीब सोची।"},{"emoji":"🪞💧","title":"कुएँ में शेर","text":"खरगोश शेर को एक कुएँ के पास ले गया। शेर ने पानी में अपनी परछाईं देखी।"},{"emoji":"🐰🎉","title":"सब खुश","text":"शेर कुएँ में कूद पड़ा। सब जानवर खुश हो गए। बुद्धि ताकत से बड़ी होती है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__mathematics__c1__t1','English','{"storyTitle":"The Bead Shop of Hundreds","scenes":[{"emoji":"🧿🏪","title":"A Shop of Beads","text":"Zara’s uncle sold beads. He packed 10 beads in a packet and 10 packets in a box."},{"emoji":"📦💯","title":"Ten Tens Make a Hundred","text":"A box held 10 packets of 10 beads. That is 100 beads."},{"emoji":"2️⃣4️⃣7️⃣","title":"Two Hundred Forty-Seven","text":"2 boxes, 4 packets and 7 loose beads made 247. Each digit has its place value."},{"emoji":"🔢😊","title":"Reading Big Numbers","text":"Zara read numbers as hundreds, then tens, then ones. Big numbers are just groups."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__mathematics__c1__t2','English','{"storyTitle":"The Frog on the Number Line","scenes":[{"emoji":"🐸➡️","title":"A Jumping Frog","text":"Fiona the frog jumped along the number line. She liked to jump in equal steps."},{"emoji":"2️⃣4️⃣6️⃣8️⃣","title":"Jumping by Twos","text":"2, 4, 6, 8, 10… Fiona skipped one number each time."},{"emoji":"5️⃣0️⃣","title":"Jumping by Fives","text":"5, 10, 15, 20… the numbers all ended in 5 or 0."},{"emoji":"🔟🏆","title":"Jumping by Tens","text":"10, 20, 30… Skip counting is the quick way to count big groups."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__mathematics__c2__t1','English','{"storyTitle":"Collecting Stickers","scenes":[{"emoji":"📒⭐","title":"The Sticker Book","text":"Dev had 27 stickers and his sister gave him 18 more."},{"emoji":"7️⃣➕8️⃣","title":"Ones First","text":"7 ones plus 8 ones makes 15 ones. That is 1 ten and 5 ones."},{"emoji":"↗️1️⃣","title":"Carry the Ten","text":"Write 5 in the ones place and carry the 1 ten to the tens column."},{"emoji":"4️⃣5️⃣🎉","title":"The Total","text":"2 tens + 1 ten + the carried ten makes 4 tens. 27 + 18 = 45 stickers."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__mathematics__c2__t2','English','{"storyTitle":"The Cupcake Trays","scenes":[{"emoji":"🧁🍽️","title":"Trays of Cupcakes","text":"A baker put 5 cupcakes on each tray. He had 3 trays."},{"emoji":"5️⃣➕5️⃣➕5️⃣","title":"Adding Equal Groups","text":"5 + 5 + 5 = 15. Adding the same number again and again is multiplication."},{"emoji":"3️⃣✖️5️⃣🟰1️⃣5️⃣","title":"Three Fives","text":"We write 3 × 5 = 15. “Three fives are fifteen.”"},{"emoji":"📊🧁","title":"Table of Five","text":"1 × 5 = 5, 2 × 5 = 10, 3 × 5 = 15. A table lists the groups quickly."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__mathematics__c3__t1','English','{"storyTitle":"The Clock Tower","scenes":[{"emoji":"🕐🏰","title":"A Tall Clock","text":"The tower clock had two hands. The short hand shows the hour. The long hand shows the minutes."},{"emoji":"🕒🔔","title":"O’Clock","text":"When the long hand is on 12, it is an o’clock time. At 3 o’clock the bell rings three times."},{"emoji":"🕧🌙","title":"Half Past","text":"When the long hand is on 6, it is half past. Half past 4 is 4:30."},{"emoji":"⏰😊","title":"Be on Time","text":"Zoya checked the clock and reached school on time. Clocks help us plan our day."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__mathematics__c3__t2','English','{"storyTitle":"The Little Shopkeeper","scenes":[{"emoji":"🪙💵","title":"Coins and Notes","text":"Mira set up a pretend shop. She had ₹1, ₹2, ₹5 and ₹10 coins and ₹10, ₹20 notes."},{"emoji":"🍬🏷️","title":"Price Tags","text":"A toffee costs ₹2. A biscuit costs ₹5. Mira added the prices."},{"emoji":"🧮💰","title":"Making ₹10","text":"Two ₹5 coins, or five ₹2 coins, make ₹10. Many coins can make one amount."},{"emoji":"🛍️😄","title":"Fair Change","text":"She gave the right change to every customer. Money must be counted carefully."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__english__c1__t1','English','{"storyTitle":"The Lost Kitten","scenes":[{"emoji":"🐈🌧️","title":"A Rainy Day","text":"A little kitten got lost on a rainy day. She felt cold and scared."},{"emoji":"👧☂️","title":"A Kind Girl","text":"A girl named Asha saw the kitten under a bench and picked her up."},{"emoji":"🏠🥛","title":"Warm and Safe","text":"Asha took the kitten home and gave her warm milk and a soft towel."},{"emoji":"🐱🔍","title":"Who, What, Where","text":"Who found the kitten? Asha. Where was the kitten? Under a bench. Good readers ask questions."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__english__c1__t2','English','{"storyTitle":"One Cat, Many Cats","scenes":[{"emoji":"🐱","title":"One Cat","text":"Mia had one cat. One means singular."},{"emoji":"🐱🐱🐱","title":"Many Cats","text":"At the farm she saw many cats. Many means plural. Most words add -s: cat, cats."},{"emoji":"🚌🚌","title":"Add -es","text":"Words ending in s, x, ch or sh add -es: bus, buses. Box, boxes."},{"emoji":"👶👶🔄","title":"Special Words","text":"Some words change fully: child, children. Man, men. Keep an eye out for these!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__english__c2__t1','English','{"storyTitle":"The Describing Dragon","scenes":[{"emoji":"🐉✨","title":"A Dragon of Words","text":"Dilly the dragon loved to describe things. “A dragon is big and green!” she said."},{"emoji":"🔴🍎","title":"Colour Words","text":"Red apple, blue sky, yellow sun. Colour words describe how things look."},{"emoji":"🐘🐭","title":"Size Words","text":"A tall giraffe, a tiny ant, a huge elephant. Size words tell us how big or small."},{"emoji":"📝😃","title":"Describe It","text":"Adjectives make sentences colourful. Describe your school bag using three words!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__english__c2__t2','English','{"storyTitle":"Is, Am, Are at the Zoo","scenes":[{"emoji":"🦒🎟️","title":"Zoo Day","text":"Ria visited the zoo with her friends. She said, “I am so excited!”"},{"emoji":"🦁👍","title":"One Animal: Is","text":"“The lion is big.” We use is for one person or thing."},{"emoji":"🐒🐒","title":"Many Animals: Are","text":"“The monkeys are funny.” We use are for many, and for “you”."},{"emoji":"🙋‍♀️🔤","title":"I Am","text":"With I we always say am: “I am happy.” Now try your own sentences!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__evs__c1__t1','English','{"storyTitle":"The Sorting Game","scenes":[{"emoji":"🧺🔍","title":"A Basket of Things","text":"Ravi had a basket with a rock, a flower, a toy car and a puppy."},{"emoji":"🐶🌸","title":"Living Things","text":"The puppy and the flower grow, need food and water, and have babies. They are living."},{"emoji":"🪨🚗","title":"Non-living Things","text":"The rock and the toy car do not grow or eat. They are non-living."},{"emoji":"✅🌍","title":"Sort the World","text":"Ask: does it grow, eat and breathe? If yes, it is living. Now sort the things in your room."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__evs__c1__t2','English','{"storyTitle":"What We All Need","scenes":[{"emoji":"🌬️💧","title":"Air and Water","text":"All living things need air to breathe and water to drink."},{"emoji":"🍃🥕","title":"Food","text":"Plants make their own food. Animals eat plants or other animals."},{"emoji":"🏡🌳","title":"A Home","text":"Every creature needs shelter: a nest, a burrow or a house."},{"emoji":"🌍❤️","title":"Care for Nature","text":"If we keep air clean and save water, all living things stay happy."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__evs__c2__t1','English','{"storyTitle":"The Journey of Water","scenes":[{"emoji":"🌧️⛰️","title":"Rain Falls","text":"Rain falls on hills and fields. This is the first source of water."},{"emoji":"🏞️🌊","title":"Rivers and Ponds","text":"Rain flows into streams, rivers and ponds. People use river water too."},{"emoji":"🪣🏚️","title":"Wells and Taps","text":"People also dig wells and pump water from under the ground. Pipes bring it to taps."},{"emoji":"🚰🙏","title":"Thank You, Water","text":"Water reaches our homes after a long journey. Never waste it."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__evs__c2__t2','English','{"storyTitle":"Drip the Drop","scenes":[{"emoji":"💧😢","title":"A Sad Drop","text":"Drip the water drop felt sad. A tap in the house was leaking all night."},{"emoji":"🚿🧒","title":"Short Showers","text":"“Take a short bath and close the tap,” said Drip. Every drop counts."},{"emoji":"🪥🚰","title":"Brushing Smartly","text":"Switch off the tap while brushing your teeth. That saves many glasses of water."},{"emoji":"🌳💧😊","title":"Happy Drops","text":"Water used wisely can water plants, too. Drip was happy again."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__hindi__c1__t1','English','{"storyTitle":"मात्राओं का मेला","scenes":[{"emoji":"🎪✨","title":"मेला लगा","text":"आज मात्राओं का मेला लगा था। हर मात्रा अपना खेल दिखा रही थी।"},{"emoji":"🐘🧵","title":"आ की मात्रा","text":"कमल में आ की मात्रा लगी तो बना कमला। “आम”, “काला” और “नाक” भी बने।"},{"emoji":"📘🐠","title":"इ और ई की मात्रा","text":"“किताब” में छोटी इ है। “मछली” में बड़ी ई की मात्रा है।"},{"emoji":"📖😃","title":"शब्द पढ़ो","text":"मात्राएँ लगाने से नए शब्द बनते हैं। तुम भी पाँच शब्द बनाओ।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__hindi__c1__t2','English','{"storyTitle":"उल्लू और ऊँट","scenes":[{"emoji":"🦉🌙","title":"उल्लू","text":"रात में एक उल्लू पेड़ पर बैठा था। “उ” की मात्रा नीचे लगती है।"},{"emoji":"🐫🏜️","title":"ऊँट","text":"ऊँट रेगिस्तान में रहता है। “ऊ” की मात्रा भी नीचे लगती है, पर उसकी पूँछ लंबी है।"},{"emoji":"🌺🍋","title":"और शब्द","text":"फूल, चूहा, सूरज और ऊन में उ-ऊ की मात्राएँ हैं।"},{"emoji":"🎯🔤","title":"पहचानो","text":"तुम्हारे आस-पास कौन-से शब्दों में उ या ऊ की मात्रा है?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__hindi__c2__t1','English','{"storyTitle":"एक और बहुत","scenes":[{"emoji":"🍎","title":"एक सेब","text":"रीमा के पास एक सेब था। एक के लिए एकवचन शब्द होता है।"},{"emoji":"🍎🍎🍎","title":"तीन सेब","text":"माँ ने और सेब दिए। अब बहुत सारे सेब थे। यह बहुवचन है।"},{"emoji":"🐶🐕","title":"कुत्ता, कुत्ते","text":"कुत्ता का बहुवचन कुत्ते होता है। लड़का का लड़के।"},{"emoji":"👧👧","title":"पहचान करो","text":"किताब का बहुवचन किताबें, लड़की का लड़कियाँ। अब तुम बताओ।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__hindi__c2__t2','English','{"storyTitle":"उलटी दुनिया","scenes":[{"emoji":"🙃🌍","title":"उलटी दुनिया","text":"एक दिन दुनिया उलटी हो गई। जो बड़ा था वह छोटा हो गया।"},{"emoji":"☀️🌙","title":"दिन और रात","text":"दिन का उलटा रात। ऊपर का उलटा नीचे।"},{"emoji":"🔥💧","title":"गरम और ठंडा","text":"गरम का उलटा ठंडा। मीठा का उलटा कड़वा।"},{"emoji":"🎲✨","title":"जोड़ी बनाओ","text":"उलटे अर्थ वाले शब्द विलोम कहलाते हैं। कुछ और जोड़ियाँ ढूँढ़ो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__hindi__c3__t1','English','{"storyTitle":"जल की रानी","scenes":[{"emoji":"🐟👑","title":"जल की रानी","text":"एक नन्ही मछली पानी में रहती थी। सब उसे जल की रानी कहते थे।"},{"emoji":"🌊🏠","title":"जल ही उसका जीवन","text":"पानी उसका घर है। वह पानी में तैरती है और साँस लेती है।"},{"emoji":"👶🤲","title":"हाथ लगाओगे तो डर जाएगी","text":"जब हम उसे पानी से बाहर निकालते हैं तो वह घबरा जाती है।"},{"emoji":"🐠❤️","title":"मछली से प्यार","text":"हम मछली को पानी में ही खुश रहने देंगे। सब जीवों से प्यार करो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-2__hindi__c3__t2','English','{"storyTitle":"दो दोस्त और भालू","scenes":[{"emoji":"👬🌲","title":"दो दोस्त","text":"दो दोस्त जंगल से जा रहे थे। दोनों में गहरी दोस्ती थी।"},{"emoji":"🐻😨","title":"भालू आया","text":"अचानक एक भालू दिखा। एक दोस्त झट से पेड़ पर चढ़ गया।"},{"emoji":"😮🤫","title":"चुप रहो","text":"दूसरा दोस्त ज़मीन पर लेट गया। भालू ने उसे सूँघा और चला गया।"},{"emoji":"🤝💛","title":"सच्चा दोस्त","text":"मुश्किल में जो साथ दे, वही सच्चा दोस्त है। हम भी दोस्तों का साथ देंगे।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__mathematics__c1__t1','English','{"storyTitle":"The Thousand Stamps","scenes":[{"emoji":"📮🏫","title":"The Stamp Collection","text":"Arjun’s school collected stamps. They packed 100 stamps in each pouch."},{"emoji":"📬1️⃣0️⃣","title":"Ten Pouches","text":"Ten pouches of 100 make 1000 stamps. That is one thousand."},{"emoji":"3️⃣2️⃣4️⃣6️⃣","title":"Reading 3246","text":"Three thousands, two hundreds, four tens, six ones: three thousand two hundred forty-six."},{"emoji":"🔢⭐","title":"Place Value Rules","text":"The same digit is worth different amounts in different places. In 3246 the 2 means 200."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__mathematics__c1__t2','English','{"storyTitle":"The Cricket Crowd","scenes":[{"emoji":"🏏🏟️","title":"A Big Match","text":"A stadium had 4,356 fans on Saturday and 4,298 on Sunday. Which day had more?"},{"emoji":"↔️🔢","title":"Compare Place by Place","text":"Start from the thousands. Both are 4. Then hundreds: 3 is more than 2. So 4,356 is greater."},{"emoji":"🎯🔟","title":"Round to Ten","text":"4,298 is closer to 4,300 than 4,290. Rounding gives a handy, friendly number."},{"emoji":"📣😊","title":"About a Hundred","text":"Rounded to the nearest hundred, the crowd was about 4,400 and 4,300."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__mathematics__c2__t1','English','{"storyTitle":"The Mango Crates","scenes":[{"emoji":"🥭📦","title":"Crates of Mangoes","text":"A farmer packed 6 mangoes in each crate. He filled 4 crates."},{"emoji":"6️⃣✖️4️⃣","title":"Four Sixes","text":"6 + 6 + 6 + 6 = 24. We write 4 × 6 = 24."},{"emoji":"🔄🧮","title":"Swap and Check","text":"4 × 6 and 6 × 4 both give 24. Swapping the numbers does not change the answer."},{"emoji":"📊🥭","title":"Table of Six","text":"6, 12, 18, 24, 30… Tables are built by adding the same number each time."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__mathematics__c2__t2','English','{"storyTitle":"The Birthday Sweets","scenes":[{"emoji":"🎂🍬","title":"Sweets to Share","text":"At a birthday party there were 12 sweets and 4 friends."},{"emoji":"🤝🍬","title":"Fair Sharing","text":"Each friend got one sweet at a time, until all were shared. Each got 3."},{"emoji":"1️⃣2️⃣➗4️⃣🟰3️⃣","title":"Division Sign","text":"12 ÷ 4 = 3. Division means sharing equally or making equal groups."},{"emoji":"🔁✖️","title":"Division Undoes Multiplication","text":"Since 4 × 3 = 12, we know 12 ÷ 4 = 3. They are partners."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__mathematics__c3__t1','English','{"storyTitle":"The Pizza Party","scenes":[{"emoji":"🍕🎉","title":"A Big Pizza","text":"A pizza arrived for four hungry friends."},{"emoji":"➗2️⃣","title":"Cut in Half","text":"Cut into two equal parts, each piece is half, written 1/2."},{"emoji":"4️⃣🍕","title":"Quarters","text":"Cut into four equal parts, each piece is a quarter, written 1/4."},{"emoji":"⚖️😋","title":"Equal Parts Only","text":"Fractions need equal parts. Four equal pieces mean everyone shares fairly."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__mathematics__c3__t2','English','{"storyTitle":"The Tailor, the Grocer and the Milkman","scenes":[{"emoji":"📏🧵","title":"The Tailor","text":"A tailor measured cloth in metres and centimetres. 1 metre is 100 centimetres."},{"emoji":"⚖️🍚","title":"The Grocer","text":"A grocer weighed rice in kilograms and grams. 1 kilogram is 1000 grams."},{"emoji":"🥛🫙","title":"The Milkman","text":"A milkman poured milk in litres and millilitres. 1 litre is 1000 millilitres."},{"emoji":"🧰✅","title":"Right Tool, Right Unit","text":"Use a ruler for length, a scale for weight and a jug for liquid. Always pick the right unit."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__english__c1__t1','English','{"storyTitle":"The Honest Woodcutter","scenes":[{"emoji":"🪓🌲","title":"A Poor Woodcutter","text":"A poor woodcutter cut wood by a river. One day his axe fell in the water."},{"emoji":"🧜‍♀️💧","title":"The River Spirit","text":"A river spirit rose from the water holding a golden axe. “Is this yours?” she asked."},{"emoji":"🙅‍♂️🪓","title":"The Truth","text":"“No,” said the woodcutter, “mine is the plain iron one.” He did not lie."},{"emoji":"🎁⭐","title":"The Reward","text":"The spirit gave him all three axes for his honesty. The main idea: honesty is the best policy."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__english__c1__t2','English','{"storyTitle":"The Word Builder","scenes":[{"emoji":"🧱🔤","title":"Word Blocks","text":"Zoya the word builder added little blocks to the front and end of words."},{"emoji":"😊➡️😞","title":"Un-","text":"Add un- to “happy” and you get “unhappy”. Un- often means “not”."},{"emoji":"🎨🌈","title":"-ful","text":"Add -ful to “colour” and you get “colourful”. -ful means “full of”."},{"emoji":"🐢🐌","title":"-ly","text":"Add -ly to “slow” and you get “slowly”. Small blocks make big new words."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__english__c2__t1','English','{"storyTitle":"Nouns in Disguise","scenes":[{"emoji":"🕵️🎭","title":"Who is Hiding?","text":"Detective Dev wanted to find the nouns in disguise."},{"emoji":"👩🏙️","title":"Common and Proper","text":"“Girl” is a common noun. “Anita” is a proper noun with a capital letter."},{"emoji":"👧➡️🙋","title":"Pronouns","text":"Instead of saying “Anita” again and again, we say “she”. Pronouns take the place of nouns."},{"emoji":"📝🌟","title":"Case Solved","text":"He, she, it, they, we: pronouns keep sentences short and smooth."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__english__c2__t2','English','{"storyTitle":"The Time-Travelling Train","scenes":[{"emoji":"🚂⏳","title":"All Aboard","text":"A magic train could go to yesterday, today and tomorrow."},{"emoji":"⏪🚶","title":"Past","text":"Yesterday Ria walked to school. Past tense says what already happened."},{"emoji":"▶️🏃","title":"Present","text":"Today Ria walks to school. Present tense says what happens now."},{"emoji":"⏩🚌","title":"Future","text":"Tomorrow Ria will walk to school. Future tense says what will happen."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__evs__c1__t1','English','{"storyTitle":"Breakfast Detective","scenes":[{"emoji":"🥣🕵️","title":"The Breakfast Mystery","text":"Kabir wondered where his breakfast came from."},{"emoji":"🌾🍞","title":"From Plants","text":"Bread comes from wheat, poha from rice and juice from fruits."},{"emoji":"🐄🥛","title":"From Animals","text":"Milk comes from cows and buffaloes. Eggs come from hens."},{"emoji":"🙏🌍","title":"Thank You, Farmers","text":"Plants and animals give us food. Farmers work hard so we can eat."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__evs__c1__t2','English','{"storyTitle":"The Rainbow Plate","scenes":[{"emoji":"🍽️🌈","title":"A Rainbow Plate","text":"Mum served a plate with many colours."},{"emoji":"🍚🍞","title":"Energy Foods","text":"Rice and chapati give us energy to run and play."},{"emoji":"🥚🫘","title":"Body-building Foods","text":"Dal, eggs and milk help our bodies grow strong."},{"emoji":"🥗🍊","title":"Protective Foods","text":"Vegetables and fruits protect us from illness. A balanced plate has all three."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__evs__c2__t1','English','{"storyTitle":"Who Lives Where?","scenes":[{"emoji":"🌳🦁","title":"Forest Dwellers","text":"In forests live lions, deer and monkeys. Lions eat meat; deer eat plants."},{"emoji":"🏜️🐪","title":"Desert Dwellers","text":"Camels live in deserts. They can go many days without water."},{"emoji":"🌊🐬","title":"Water Dwellers","text":"Fish and dolphins live in water. Their bodies are made for swimming."},{"emoji":"🗺️🐾","title":"Right Home for Everyone","text":"Every animal’s body and habits suit its home."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__evs__c2__t2','English','{"storyTitle":"The Nest Builders","scenes":[{"emoji":"🪶🐦","title":"Bird Bodies","text":"Birds have feathers, wings and beaks. Most birds can fly."},{"emoji":"🪺🧵","title":"Weaver Bird","text":"The weaver bird makes a hanging nest of grass."},{"emoji":"🌴🕊️","title":"Different Nests","text":"Crows build nests with sticks. Woodpeckers make holes in tree trunks."},{"emoji":"🥚🐣","title":"A New Chick","text":"Mother birds lay eggs in nests and keep them warm until chicks hatch."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__evs__c3__t1','English','{"storyTitle":"Houses Around India","scenes":[{"emoji":"🏠🗺️","title":"Many Homes","text":"People live in different houses depending on where they live."},{"emoji":"⛰️🛖","title":"Mountain Homes","text":"In cold mountains, houses have slanting roofs so snow slides off."},{"emoji":"🌊🏚️","title":"Houses on Stilts","text":"Near rivers, some houses stand on tall poles in case of floods."},{"emoji":"🏙️🏢","title":"City Flats","text":"In cities, people live in tall buildings with many flats."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__evs__c3__t2','English','{"storyTitle":"The Great Journey","scenes":[{"emoji":"🚌🛣️","title":"By Road","text":"Buses, cars and cycles run on roads. They carry us to nearby places."},{"emoji":"🚆🛤️","title":"By Rail","text":"Trains carry many people and goods across the country."},{"emoji":"🚢⛵","title":"By Water","text":"Boats and ships travel on rivers and seas."},{"emoji":"✈️☁️","title":"By Air","text":"Aeroplanes are fastest and travel the long distances. Which would you pick?"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__hindi__c1__t1','English','{"storyTitle":"नाम और सर्वनाम","scenes":[{"emoji":"🏷️👧","title":"नाम वाले शब्द","text":"किसी व्यक्ति, जगह या वस्तु के नाम को संज्ञा कहते हैं, जैसे रीमा, दिल्ली, किताब।"},{"emoji":"🔁🙋","title":"बार-बार नाम नहीं","text":"“रीमा आई। रीमा बैठी।” इसकी जगह हम कहते हैं “रीमा आई। वह बैठी।”"},{"emoji":"🅰️🔤","title":"सर्वनाम","text":"मैं, तुम, वह, हम, वे: ये सर्वनाम हैं। ये नाम की जगह आते हैं।"},{"emoji":"✅📚","title":"पहचानो","text":"“राम ने आम खाया। वह खुश था।” इसमें राम, आम संज्ञा हैं और वह सर्वनाम है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__hindi__c1__t2','English','{"storyTitle":"समय की गाड़ी","scenes":[{"emoji":"🚂⏰","title":"समय की गाड़ी","text":"एक जादुई गाड़ी बीते कल, आज और आने वाले कल में जाती थी।"},{"emoji":"⏪🏏","title":"भूत काल","text":"“कल मैंने क्रिकेट खेला।” जो बीत चुका है, वह भूत काल है।"},{"emoji":"▶️🏏","title":"वर्तमान काल","text":"“मैं क्रिकेट खेल रहा हूँ।” जो अभी हो रहा है, वह वर्तमान काल है।"},{"emoji":"⏩🏏","title":"भविष्य काल","text":"“मैं कल क्रिकेट खेलूँगा।” जो आगे होगा, वह भविष्य काल है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__hindi__c2__t1','English','{"storyTitle":"दोस्त के नाम चिट्ठी","scenes":[{"emoji":"✉️👦","title":"चिट्ठी लिखो","text":"अमन ने अपने दोस्त को चिट्ठी लिखने की सोची।"},{"emoji":"📅📍","title":"तारीख और जगह","text":"पत्र के ऊपर तारीख और जगह लिखते हैं।"},{"emoji":"💌😊","title":"संबोधन और बात","text":"“प्रिय मित्र” लिखकर अपनी बात लिखो। अंत में “तुम्हारा मित्र” और अपना नाम।"},{"emoji":"📮🎉","title":"डाक में डालो","text":"अमन ने चिट्ठी लिफ़ाफ़े में रखकर डाकघर में डाल दी।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__hindi__c2__t2','English','{"storyTitle":"पेड़ हमारे दोस्त","scenes":[{"emoji":"🌳📖","title":"एक अनुच्छेद","text":"पेड़ हमें छाया, फल और हवा देते हैं।"},{"emoji":"🌬️🫁","title":"साफ़ हवा","text":"पेड़ गंदी हवा लेकर साफ़ हवा देते हैं, ताकि हम अच्छी तरह साँस ले सकें।"},{"emoji":"🐦🪺","title":"पक्षियों का घर","text":"कई पक्षी पेड़ पर घोंसला बनाते हैं।"},{"emoji":"🌱🙌","title":"पेड़ लगाओ","text":"मुख्य बात: पेड़ हमारे दोस्त हैं। हमें पेड़ लगाने चाहिए और उन्हें बचाना चाहिए।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__hindi__c3__t1','English','{"storyTitle":"चतुर बंदर","scenes":[{"emoji":"🐒🍎","title":"जामुन का पेड़","text":"एक बंदर नदी किनारे जामुन के पेड़ पर रहता था। वह मगरमच्छ को जामुन खिलाता था।"},{"emoji":"🐊😈","title":"मगर की चाल","text":"मगर की पत्नी ने बंदर का दिल माँगा। मगर बंदर को पीठ पर बिठाकर चल दिया।"},{"emoji":"🧠💡","title":"बंदर की चतुराई","text":"बंदर ने कहा, “मेरा दिल तो पेड़ पर रखा है।” मगर उसे वापस ले आया।"},{"emoji":"🐒🎉","title":"बच गया","text":"बंदर पेड़ पर कूद गया। सीख: मुसीबत में घबराओ नहीं, सोच-समझकर काम लो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-3__hindi__c3__t2','English','{"storyTitle":"चिड़िया रानी","scenes":[{"emoji":"🐦🌅","title":"सुबह की चिड़िया","text":"सुबह होते ही चिड़िया रानी चहचहाने लगी।"},{"emoji":"🌾🪺","title":"दाना-पानी","text":"वह दाना चुगती है और अपने बच्चों के लिए घोंसला बनाती है।"},{"emoji":"☁️🕊️","title":"ऊँची उड़ान","text":"चिड़िया पंख फैलाकर आसमान में ऊँची उड़ती है।"},{"emoji":"🧒❤️","title":"हमारी सहेली","text":"हम चिड़ियों को दाना और पानी देंगे। वे हमारी सहेली हैं।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__mathematics__c1__t1','English','{"storyTitle":"The Lakh Rupee Rangoli Contest","scenes":[{"emoji":"🏆🪔","title":"The Rangoli Contest","text":"A town held a rangoli contest. The prize was ₹50,000, and many people wanted to guess how many flowers were used."},{"emoji":"🌼🔢","title":"Ten Thousands","text":"Ten thousands, thousands, hundreds, tens and ones: each place is ten times the one on its right."},{"emoji":"5️⃣4️⃣3️⃣2️⃣1️⃣","title":"Reading 54,321","text":"54,321 is fifty-four thousand three hundred twenty-one. We use commas after the thousands place."},{"emoji":"💯🎉","title":"Almost a Lakh","text":"99,999 is the biggest 5-digit number. Add one more and you reach 1,00,000 — one lakh."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__mathematics__c1__t2','English','{"storyTitle":"The Quick Guess Shop","scenes":[{"emoji":"🛒🤔","title":"A Fast Guess","text":"Veena wanted to know the total of her shopping bill quickly. She did not need the exact amount."},{"emoji":"🎯🔢","title":"Round Each Number","text":"She rounded ₹498 to ₹500 and ₹203 to ₹200. Rounded numbers are easy to add."},{"emoji":"➕🪙","title":"Estimate the Sum","text":"500 + 200 is about ₹700. The exact bill was ₹701, which was very close."},{"emoji":"✅🧠","title":"Check Your Answer","text":"Estimating is a quick way to check if an answer is sensible."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__mathematics__c2__t1','English','{"storyTitle":"The Chocolate Box Puzzle","scenes":[{"emoji":"🍫📦","title":"The Chocolate Box","text":"Kavya had 12 chocolates and wanted to pack them in equal rows."},{"emoji":"1️⃣2️⃣🧮","title":"Factors of 12","text":"She could make rows of 1, 2, 3, 4, 6 or 12. These numbers divide 12 exactly: they are its factors."},{"emoji":"4️⃣8️⃣1️⃣2️⃣","title":"Multiples of 4","text":"4, 8, 12, 16, 20… the numbers in the table of 4 are its multiples."},{"emoji":"🔗🌟","title":"Factor Meets Multiple","text":"If 4 is a factor of 12, then 12 is a multiple of 4. They are two sides of the same coin."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__mathematics__c2__t2','English','{"storyTitle":"The School Bus Trips","scenes":[{"emoji":"🚌🏫","title":"Trips Across Town","text":"A school bus carries 45 children per trip. It made 6 trips."},{"emoji":"4️⃣5️⃣✖️6️⃣","title":"Multiply Step by Step","text":"6 × 5 ones = 30, 6 × 4 tens = 240. Add them: 270 children in all."},{"emoji":"2️⃣7️⃣0️⃣➗8️⃣","title":"Dividing with a Remainder","text":"If 270 children share 8 cars equally, each gets 33 and 6 are left over. The leftover is the remainder."},{"emoji":"🔍✅","title":"Check by Multiplying","text":"33 × 8 + 6 = 270. Multiplication checks division."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__mathematics__c3__t1','English','{"storyTitle":"Parts of a Paratha","scenes":[{"emoji":"🫓👨‍👩‍👧","title":"One Paratha for Many","text":"Mum cut a paratha into 10 equal parts for the family."},{"emoji":"3️⃣🔟","title":"Three-Tenths","text":"Dad ate 3 parts. That is 3/10 of the paratha."},{"emoji":"0️⃣🔹3️⃣","title":"A Decimal Way","text":"3/10 can also be written as 0.3. The dot is a decimal point."},{"emoji":"⚖️😋","title":"Compare","text":"2/10 is less than 3/10. When parts are the same size, more parts means more."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__mathematics__c3__t2','English','{"storyTitle":"The Garden Fence","scenes":[{"emoji":"🌷🏡","title":"Gita’s Garden","text":"Gita’s rectangular garden was 8 m long and 5 m wide. She wanted to fence it."},{"emoji":"📏🔁","title":"Perimeter","text":"The fence goes around the edge: 8 + 5 + 8 + 5 = 26 m. Perimeter is the distance around."},{"emoji":"🟩🟩","title":"Area","text":"To cover the garden with grass squares, count the squares: 8 × 5 = 40 square metres."},{"emoji":"🧱🌱","title":"Two Different Ideas","text":"Perimeter is the boundary and area is the space inside. We need both for a garden."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__english__c1__t1','English','{"storyTitle":"The Clever Crow and the Pebbles","scenes":[{"emoji":"🐦☀️","title":"The Thirsty Crow","text":"On a hot day, a crow flew far looking for water. She was very thirsty."},{"emoji":"🏺🪨","title":"A Tall Jar","text":"She found a jar with a little water at the bottom. Her beak could not reach it."},{"emoji":"🧠💡","title":"A Clever Idea","text":"She dropped pebbles in one by one until the water rose to the top."},{"emoji":"📖🌟","title":"Understanding the Story","text":"Character: the clever crow. Setting: a hot day. Lesson: where there is a will, there is a way."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__english__c1__t2','English','{"storyTitle":"The Paragraph Sandwich","scenes":[{"emoji":"🥪✍️","title":"A Writing Sandwich","text":"Anil’s teacher said a paragraph is like a sandwich."},{"emoji":"🍞☝️","title":"The Top Slice","text":"The first sentence tells the main idea: “My school has a lovely garden.”"},{"emoji":"🥬🍅","title":"The Filling","text":"The middle sentences add details: roses, a mango tree and a swing."},{"emoji":"🍞🏁","title":"The Bottom Slice","text":"The last sentence closes the idea: “I love spending time there.”"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__english__c2__t1','English','{"storyTitle":"The Racing Tortoise","scenes":[{"emoji":"🐢🏁","title":"A Race","text":"Toto the tortoise entered a race."},{"emoji":"🐢🐌","title":"How?","text":"He walked slowly, but he walked steadily. “Slowly” and “steadily” tell how."},{"emoji":"⏰📍","title":"When and Where","text":"He started early and finished here. “Early” tells when. “Here” tells where."},{"emoji":"🏆😊","title":"Adverbs Win","text":"Adverbs tell us more about actions. Toto won with patience."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__english__c2__t2','English','{"storyTitle":"Hide and Seek in the Classroom","scenes":[{"emoji":"🙈🏫","title":"Hide and Seek","text":"Isha played hide and seek in the classroom with her friends."},{"emoji":"🪑⬇️","title":"Under and On","text":"Raju hid under the desk. The ball was on the shelf."},{"emoji":"🚪↔️","title":"Behind and Between","text":"Mina stood behind the door. Seema stood between two benches."},{"emoji":"🔍🎉","title":"Found You!","text":"Words like under, on, behind and between are prepositions. They tell where things are."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__evs__c1__t1','English','{"storyTitle":"The Journey of a Roti","scenes":[{"emoji":"🫓😁","title":"Bite and Chew","text":"Rohan took a bite of roti. Front teeth cut it. Back teeth ground it."},{"emoji":"👅💦","title":"Saliva","text":"Saliva in the mouth wet the roti and began breaking it down."},{"emoji":"🍽️🩺","title":"Down the Pipe","text":"The food went down the food pipe to the stomach. The stomach mixed it into a paste."},{"emoji":"🧪✅","title":"Small Intestine","text":"In the small intestine the body took in nutrients. The rest left the body. Brush your teeth twice a day!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__evs__c1__t2','English','{"storyTitle":"The Moving Skeleton","scenes":[{"emoji":"💀🏃","title":"The Skeleton","text":"The skeleton gives our body shape and protects soft organs. It has over 200 bones."},{"emoji":"🦴🔗","title":"Joints","text":"Bones meet at joints like the elbow and knee. Joints let the body bend."},{"emoji":"💪🏋️","title":"Muscles","text":"Muscles pull on bones to make them move. Strong muscles help you run, jump and lift."},{"emoji":"🥛🏃","title":"Strong for Life","text":"Milk, eggs and exercise keep bones and muscles strong."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__evs__c2__t1','English','{"storyTitle":"The Whispering Forest","scenes":[{"emoji":"🌳🌲","title":"A Big Forest","text":"A forest is a large area full of trees, plants and animals."},{"emoji":"🌬️💚","title":"Fresh Air","text":"Trees take in carbon dioxide and give out oxygen. The forest cleans our air."},{"emoji":"🐅🐒","title":"Animal Homes","text":"Tigers, monkeys, birds and insects live in forests."},{"emoji":"🪵🌱","title":"Use Wisely","text":"Forests give wood, fruit and medicines. We must plant trees and not cut too many."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__evs__c2__t2','English','{"storyTitle":"The Adventures of a Water Drop","scenes":[{"emoji":"💧🌊","title":"A Drop in the Sea","text":"Dolly the water drop floated in the sea."},{"emoji":"☀️⬆️","title":"Evaporation","text":"The sun warmed Dolly and she rose into the air as invisible vapour."},{"emoji":"☁️❄️","title":"Clouds","text":"High up it was cool. Dolly and friends joined together to form a cloud. This is condensation."},{"emoji":"🌧️🏞️","title":"Rain","text":"Heavy clouds let Dolly fall as rain. She ran back to rivers and the sea. The cycle begins again!"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__evs__c3__t1','English','{"storyTitle":"Clean Town, Green Town","scenes":[{"emoji":"🏭💨","title":"Air Pollution","text":"Smoke from vehicles and factories dirties the air."},{"emoji":"🗑️🏞️","title":"Water and Land","text":"Rubbish thrown in rivers and fields spoils them."},{"emoji":"🚲🌳","title":"What We Can Do","text":"Walk or cycle for short trips, plant trees and do not litter."},{"emoji":"♻️🌍","title":"The 3 Rs","text":"Reduce, reuse and recycle. Small steps keep our Earth clean."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__evs__c3__t2','English','{"storyTitle":"The Resource Heroes","scenes":[{"emoji":"💡🔌","title":"Electricity","text":"Switch off lights and fans when not needed. Energy is made from limited resources."},{"emoji":"🚿🪣","title":"Water","text":"Fix leaking taps and reuse water for plants."},{"emoji":"📄🌲","title":"Paper","text":"Paper comes from trees. Use both sides and recycle used paper."},{"emoji":"🦸‍♀️🌏","title":"You Can Be a Hero","text":"Saving resources protects the planet for children in the future."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__hindi__c1__t1','English','{"storyTitle":"रंग-बिरंगा बाज़ार","scenes":[{"emoji":"🏪🌈","title":"रंग-बिरंगा बाज़ार","text":"मेले में रंग-बिरंगा बाज़ार लगा था। हर चीज़ की कुछ खासियत थी।"},{"emoji":"🍎🍋","title":"गुण और रंग","text":"लाल सेब, पीला नींबू, मीठा आम। लाल, पीला और मीठा विशेषण हैं।"},{"emoji":"🐘🐜","title":"आकार और संख्या","text":"बड़ा हाथी, छोटी चींटी, चार केले। ये भी विशेषण हैं।"},{"emoji":"🏷️✨","title":"विशेषण पहचानो","text":"जो शब्द संज्ञा या सर्वनाम की विशेषता बताए, वह विशेषण कहलाता है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__hindi__c1__t2','English','{"storyTitle":"काम बोलते हैं","scenes":[{"emoji":"🏃‍♂️🌟","title":"काम के शब्द","text":"“मोहन दौड़ता है।” दौड़ना काम है, इसलिए यह क्रिया है।"},{"emoji":"📖🖊️","title":"और क्रियाएँ","text":"खाना, पीना, पढ़ना, लिखना, हँसना: ये सब क्रियाएँ हैं।"},{"emoji":"👦➡️🍎","title":"कर्ता और कर्म","text":"“राम ने सेब खाया।” खाने वाला राम कर्ता है, और जिसे खाया वह सेब कर्म है।"},{"emoji":"✅🙌","title":"खुद बनाओ","text":"अपनी दिनचर्या के पाँच वाक्य बनाओ और क्रियाएँ चुनकर बताओ।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__hindi__c2__t1','English','{"storyTitle":"सच्चा लकड़हारा","scenes":[{"emoji":"🪓🌲","title":"गरीब लकड़हारा","text":"एक गरीब लकड़हारा जंगल में लकड़ियाँ काटता था। उसकी कुल्हाड़ी नदी में गिर गई।"},{"emoji":"👼🌊","title":"जलदेवता","text":"जलदेवता सोने की कुल्हाड़ी लेकर आए। लकड़हारे ने कहा, “यह मेरी नहीं है।”"},{"emoji":"⚙️🪓","title":"अपनी कुल्हाड़ी","text":"उसने अपनी साधारण लोहे की कुल्हाड़ी पहचानी और वही माँगी।"},{"emoji":"🎁😊","title":"ईमानदारी का फल","text":"जलदेवता खुश होकर उसे तीनों कुल्हाड़ियाँ दे गए। ईमानदारी सबसे अच्छी नीति है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__hindi__c2__t2','English','{"storyTitle":"आओ पेड़ लगाएँ","scenes":[{"emoji":"🌱⛏️","title":"नन्हा पौधा","text":"आओ हम सब मिलकर एक नन्हा पौधा लगाएँ।"},{"emoji":"💧🧒","title":"देखभाल","text":"रोज़ उसमें पानी डालें और उसकी देखभाल करें।"},{"emoji":"🌳🍃","title":"छाया और फल","text":"कुछ सालों में वह बड़ा पेड़ बनेगा और हमें छाया और फल देगा।"},{"emoji":"🌍💚","title":"हरी धरती","text":"हर बच्चा एक पेड़ लगाए, तो हमारी धरती हरी-भरी हो जाएगी।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__hindi__c3__t1','English','{"storyTitle":"मेरा प्यारा विद्यालय","scenes":[{"emoji":"🏫✏️","title":"शुरुआत","text":"“मेरा विद्यालय मेरे घर के पास है।” पहला वाक्य विषय बताता है।"},{"emoji":"👩‍🏫📚","title":"बीच की बातें","text":"वहाँ अच्छे अध्यापक पढ़ाते हैं। हमारे पास बड़ा पुस्तकालय है।"},{"emoji":"⚽🌳","title":"खेल और बाग","text":"खेल के मैदान में हम खेलते हैं। बाग में खूब फूल खिलते हैं।"},{"emoji":"🏁❤️","title":"अंत","text":"“मुझे अपने विद्यालय से बहुत प्यार है।” अंतिम वाक्य बात पूरी करता है।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-4__hindi__c3__t2','English','{"storyTitle":"छुट्टी की अर्ज़ी","scenes":[{"emoji":"🤒🏠","title":"ज़रूरत","text":"सुमित को बुखार था। वह स्कूल नहीं जा सकता था।"},{"emoji":"👨‍🏫📝","title":"किसे लिखें","text":"पत्र प्रधानाचार्य को लिखा जाता है। सबसे ऊपर “सेवा में” लिखते हैं।"},{"emoji":"📄🙏","title":"विषय और निवेदन","text":"विषय लिखो: “अवकाश हेतु प्रार्थना पत्र”। फिर विनम्रता से कारण लिखो।"},{"emoji":"✍️📅","title":"अंत में","text":"अंत में “आपका आज्ञाकारी शिष्य”, अपना नाम, कक्षा और तारीख लिखो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__mathematics__c1__t1','English','{"storyTitle":"The Population Poster","scenes":[{"emoji":"🏙️📊","title":"A City Poster","text":"Anaya made a poster on India’s big cities. Their populations ran into lakhs and crores."},{"emoji":"1️⃣0️⃣0️⃣0️⃣0️⃣0️⃣0️⃣","title":"Reaching One Crore","text":"Ten lakhs make one million; one hundred lakhs make one crore, written 1,00,00,000."},{"emoji":"🔢🇮🇳","title":"Indian Place Value","text":"Ones, tens, hundreds, thousands, ten thousands, lakhs, ten lakhs, crores. Commas go after the first 3 digits, then every 2."},{"emoji":"🥇📣","title":"Compare Cities","text":"The city with the larger number of crores or lakhs is bigger. Anaya ranked her cities."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__mathematics__c1__t2','English','{"storyTitle":"The BODMAS Bakery","scenes":[{"emoji":"🥐🧮","title":"A Tricky Bill","text":"A bakery bill said 3 + 4 × 2. What is the answer?"},{"emoji":"🥇📜","title":"Rules Matter","text":"BODMAS tells the order: Brackets, Orders, Division and Multiplication, then Addition and Subtraction."},{"emoji":"4️⃣✖️2️⃣➕3️⃣","title":"Multiply First","text":"4 × 2 = 8, then 3 + 8 = 11. The answer is 11, not 14."},{"emoji":"🔓➕✖️","title":"Brackets First","text":"(3 + 4) × 2 = 14. Brackets change the order. Rules help everyone get the same answer."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__mathematics__c2__t1','English','{"storyTitle":"The Recipe Mix-up","scenes":[{"emoji":"🍰🧑‍🍳","title":"A Mixed-Up Recipe","text":"A recipe needed 1/2 cup of milk and 1/3 cup of cream."},{"emoji":"🔁➗","title":"Same-Sized Parts","text":"To add 1/2 and 1/3, change both into sixths: 3/6 + 2/6 = 5/6."},{"emoji":"💰🪙","title":"Decimals","text":"₹12.50 + ₹7.25 = ₹19.75. Line up the decimal points before adding."},{"emoji":"✅🥛","title":"A Perfect Cake","text":"Equal parts and aligned points keep our adding accurate."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__mathematics__c2__t2','English','{"storyTitle":"The Cricket Scoreboard","scenes":[{"emoji":"🏏📣","title":"The Final Over","text":"Raj hit 40 runs in 50 balls. How well did he do?"},{"emoji":"💯➗","title":"Out of 100","text":"Percent means “out of 100”. 1/2 is 50%. 1/4 is 25%."},{"emoji":"2️⃣0️⃣🍎🍎","title":"Percent of a Number","text":"20% of 50 apples = 20/100 × 50 = 10 apples."},{"emoji":"🎯📈","title":"Smart Shopping","text":"A 10% discount on ₹200 saves ₹20. Percentages help us compare and save."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__mathematics__c3__t1','English','{"storyTitle":"The Aquarium Tank","scenes":[{"emoji":"🐠🧊","title":"The Fish Tank","text":"Tia’s fish tank was 40 cm long, 20 cm wide and 25 cm high."},{"emoji":"📦✖️","title":"Length × Width × Height","text":"Volume = 40 × 20 × 25 = 20,000 cubic centimetres."},{"emoji":"🥛1️⃣0️⃣0️⃣0️⃣","title":"Litres","text":"1000 cubic centimetres equals 1 litre, so the tank holds 20 litres."},{"emoji":"🐟✅","title":"Right Size","text":"Volume tells how much space something takes up. Tia filled the tank just right."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__mathematics__c3__t2','English','{"storyTitle":"The Rainfall Report","scenes":[{"emoji":"🌧️📊","title":"A Bar Graph","text":"A bar graph showed the rainfall in four months: 20, 30, 25 and 25 cm."},{"emoji":"📈👀","title":"Reading the Bars","text":"Taller bars mean more rain. The graph makes comparing easy."},{"emoji":"➕➗","title":"Average","text":"Add them (100) and divide by 4. The average is 25 cm per month."},{"emoji":"📝🌦️","title":"Using Data","text":"Averages give one number that stands for the whole group. Weather reports use them every day."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__english__c1__t1','English','{"storyTitle":"The Mystery of the Empty Lunchbox","scenes":[{"emoji":"🍱😲","title":"The Empty Lunchbox","text":"At recess, Nisha opened her lunchbox. It was empty, with only crumbs inside."},{"emoji":"🔍👣","title":"Clues","text":"There were small muddy paw prints near her bag, and a happy puppy with a sticky nose."},{"emoji":"🐕💡","title":"Inference","text":"Nisha did not see the puppy eat, but the clues told her. Using clues to work something out is inference."},{"emoji":"📖✨","title":"Read Between the Lines","text":"Good readers use what the text says and what they already know to understand more."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__english__c1__t2','English','{"storyTitle":"Letter to Grandpa and a Note to the Principal","scenes":[{"emoji":"👴💌","title":"Informal Letter","text":"To Grandpa, Isha wrote with a friendly tone: “Dear Grandpa, I miss you…”"},{"emoji":"🏫📨","title":"Formal Letter","text":"To the Principal she wrote politely: “Respected Sir/Madam, I request…”"},{"emoji":"📍📅","title":"Parts of a Letter","text":"Address, date, greeting, body, closing and signature. Each part has a place."},{"emoji":"✅😊","title":"Right Tone","text":"Warm and friendly for family, polite and clear for school. Pick the right style."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__english__c2__t1','English','{"storyTitle":"The Link Words","scenes":[{"emoji":"🔗📝","title":"Joining Words","text":"Short sentences can be linked: “I was tired. I played.”"},{"emoji":"➕🔀","title":"And and But","text":"“I was tired but I played.” But shows a surprise. And adds an idea."},{"emoji":"❓➡️","title":"Because and So","text":"“I stayed in because it rained.” “It rained, so I stayed in.” Because gives a reason and so shows a result."},{"emoji":"🎉🏗️","title":"Build Your Own","text":"Link words make sentences smooth. Join two of your own ideas."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__english__c2__t2','English','{"storyTitle":"Who Did It?","scenes":[{"emoji":"⚽🪟","title":"A Broken Window","text":"Dev kicked the ball and broke the window."},{"emoji":"🦸‍♂️➡️","title":"Active Voice","text":"“Dev broke the window.” The doer comes first. This is active voice."},{"emoji":"🪟➡️","title":"Passive Voice","text":"“The window was broken by Dev.” The thing comes first. This is passive voice."},{"emoji":"🔄✅","title":"Choose Wisely","text":"Use active to be clear and direct. Use passive when the doer is unknown or not important."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__evs__c1__t1','English','{"storyTitle":"The Sun’s Family","scenes":[{"emoji":"☀️🌍","title":"The Sun","text":"The Sun is a star at the centre. Eight planets travel around it."},{"emoji":"🪐🔥","title":"Inner Planets","text":"Mercury, Venus, Earth and Mars are close to the Sun. They are small and rocky."},{"emoji":"🪐❄️","title":"Outer Planets","text":"Jupiter, Saturn, Uranus and Neptune are huge and far away. Jupiter is the biggest."},{"emoji":"🌍❤️","title":"Our Special Home","text":"Earth has air, water and the right warmth for life. We must take care of it."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__evs__c1__t2','English','{"storyTitle":"Why Do We Have Day and Night?","scenes":[{"emoji":"🌍🔄","title":"Earth Spins","text":"Earth spins like a top. One spin takes about 24 hours."},{"emoji":"🌞🌙","title":"Day and Night","text":"The side facing the Sun has day. The side facing away has night."},{"emoji":"🌍🛤️","title":"A Year","text":"Earth also goes around the Sun once a year, tilted a little."},{"emoji":"🍂❄️","title":"Seasons","text":"The tilt means different parts get more or less sunlight. This gives us summer, winter and the other seasons."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__evs__c2__t1','English','{"storyTitle":"Inside the Runner","scenes":[{"emoji":"🏃‍♀️💨","title":"A Fast Run","text":"Tara ran a race. Her breathing and heartbeat both sped up."},{"emoji":"🫁🌬️","title":"Lungs","text":"Her lungs took in oxygen from the air and sent out carbon dioxide."},{"emoji":"❤️🩸","title":"Heart and Blood","text":"Her heart pumped blood to carry oxygen to every part of her body."},{"emoji":"😮‍💨💪","title":"Healthy Habits","text":"Exercise makes the heart and lungs stronger. Clean air and sleep help too."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__evs__c2__t2','English','{"storyTitle":"The Safety Superheroes","scenes":[{"emoji":"🧼🦠","title":"Hygiene","text":"Washing hands removes germs. Germs cause many illnesses."},{"emoji":"💉🛡️","title":"Vaccines","text":"Vaccines teach the body to fight a disease before it arrives."},{"emoji":"🩹🚑","title":"First Aid","text":"For a small cut, wash it, cover it and tell an adult. For bad injuries, call for help."},{"emoji":"🦸‍♀️❤️","title":"Stay Safe","text":"Healthy habits and safety rules keep us strong and safe."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__evs__c3__t1','English','{"storyTitle":"The Treasure Under Our Feet","scenes":[{"emoji":"🌍💎","title":"Natural Treasures","text":"Soil, water, minerals and forests are natural resources."},{"emoji":"⛏️🏔️","title":"Minerals","text":"Coal, iron and other minerals come from underground and make things we use."},{"emoji":"🌾🌱","title":"Soil","text":"Fertile soil grows our food. Trees and plants hold soil together."},{"emoji":"♻️🙏","title":"Use Carefully","text":"Some resources do not grow back. We save them for the future."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__evs__c3__t2','English','{"storyTitle":"One India, Many Colours","scenes":[{"emoji":"🇮🇳🌈","title":"Many Colours","text":"India has many languages, clothes, foods and festivals."},{"emoji":"🎆🪔","title":"Festivals","text":"Diwali, Eid, Christmas, Pongal and Baisakhi are celebrated by people everywhere."},{"emoji":"🍛🥘","title":"Foods","text":"Dosa, rajma-chawal, dhokla and fish curry: each region has special dishes."},{"emoji":"🤝🇮🇳","title":"Unity","text":"Different ways of life make us richer. We respect and enjoy every culture."}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__hindi__c1__t1','English','{"storyTitle":"शब्दों का मेल","scenes":[{"emoji":"🧩📖","title":"शब्दों की जोड़ी","text":"दो शब्द कभी एक होकर नया रूप ले लेते हैं।"},{"emoji":"🏫🔤","title":"संधि","text":"विद्या + आलय = विद्यालय। जब दो ध्वनियाँ मिलती हैं तो संधि होती है।"},{"emoji":"🏠🚪","title":"समास","text":"राजा का पुत्र = राजपुत्र। कई शब्द मिलकर छोटा-सा नया शब्द बनाते हैं।"},{"emoji":"✨📝","title":"खुद ढूँढ़ो","text":"पाठ से ऐसे पाँच शब्द ढूँढ़ो और उन्हें अलग-अलग करके देखो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__hindi__c1__t2','English','{"storyTitle":"मुहावरों की दुकान","scenes":[{"emoji":"🏪🗣️","title":"मुहावरों की दुकान","text":"एक दुकान में हर चीज़ का अनोखा अर्थ था।"},{"emoji":"👀😮","title":"आँखें खुलना","text":"“यात्रा के बाद मेरी आँखें खुल गईं।” मतलब: सच समझ में आ गया।"},{"emoji":"🔥💧","title":"आग में घी","text":"“झगड़े में उसने आग में घी डाल दिया।” मतलब: गुस्सा और बढ़ा देना।"},{"emoji":"🎯✅","title":"प्रयोग करो","text":"हर मुहावरे का अपना अर्थ है। इन्हें अपने वाक्यों में प्रयोग करो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__hindi__c2__t1','English','{"storyTitle":"मेरा भारत","scenes":[{"emoji":"🇮🇳🌅","title":"मेरा भारत","text":"यह हमारी मातृभूमि है। इसके पर्वत, नदियाँ और खेत हमें प्यारे हैं।"},{"emoji":"🏔️🌊","title":"प्यारी धरती","text":"उत्तर में हिमालय है और दक्षिण में सागर। देश के हर हिस्से की अपनी सुंदरता है।"},{"emoji":"👨‍🌾🪖","title":"जवान और किसान","text":"किसान अन्न उगाते हैं और जवान सीमा पर देश की रक्षा करते हैं।"},{"emoji":"🤝💪","title":"हम भी करें","text":"हम पढ़ाई करें, ईमानदार बनें और देश की सेवा करें।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__hindi__c2__t2','English','{"storyTitle":"डॉ. कलाम की सीख","scenes":[{"emoji":"📰🚲","title":"अखबार वाला बालक","text":"छोटे अब्दुल कलाम सुबह साइकिल पर अखबार बाँटते थे और पढ़ाई भी करते थे।"},{"emoji":"🚀📚","title":"सपने और मेहनत","text":"उन्होंने बहुत मन लगाकर पढ़ाई की और वैज्ञानिक बने। रॉकेट बनाने में उनका बड़ा योगदान था।"},{"emoji":"🇮🇳🏅","title":"देश के राष्ट्रपति","text":"वे बच्चों से बहुत प्यार करते थे। बाद में वे देश के राष्ट्रपति बने।"},{"emoji":"🌟🙏","title":"हमारी सीख","text":"बड़े सपने देखो, कठिन परिश्रम करो और कभी हार मत मानो।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__hindi__c3__t1','English','{"storyTitle":"मेरा प्रिय त्योहार","scenes":[{"emoji":"🪔📝","title":"विषय चुनो","text":"सीमा ने निबंध के लिए “दीपावली” चुनी।"},{"emoji":"🎆🍬","title":"मध्य","text":"वह लिखती है कि दीप जलते हैं, मिठाइयाँ बनती हैं और सब एक-दूसरे से मिलते हैं।"},{"emoji":"🏠🧹","title":"तैयारी","text":"घर की सफ़ाई होती है और रंगोली सजती है।"},{"emoji":"🏁😊","title":"निष्कर्ष","text":"अंत में वह लिखती है, “दीपावली अंधेरे को दूर करके प्रकाश फैलाती है।”"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
insert into topic_content(topic_id,language,content) values('class-5__hindi__c3__t2','English','{"storyTitle":"प्रधानाचार्य जी को पत्र","scenes":[{"emoji":"📮🏫","title":"पत्र क्यों","text":"कक्षा में पंखे खराब थे, इसलिए आरव ने पत्र लिखा।"},{"emoji":"📍📅","title":"पता और तारीख","text":"ऊपर अपना पता और तारीख लिखी। फिर “सेवा में” और प्रधानाचार्य का नाम।"},{"emoji":"✍️🙏","title":"विषय और बात","text":"विषय लिखकर विनम्र शब्दों में अपनी समस्या बताई।"},{"emoji":"🖋️✅","title":"समापन","text":"अंत में “आपका आज्ञाकारी शिष्य” लिखा और अपना नाम और कक्षा लिखी।"}],"questions":[],"strong":[],"weak":[]}'::jsonb) on conflict(topic_id,language) do update set content=excluded.content;
